4.text:
For the Stokes flow write the stream function

\begin{equation*}
\psi (x,z)=f(z)\sin kx\qquad 
u_{x}=\psi_{z}=f'\sin kx\,,\qquad 
u_{z}=-\psi_{x}=-k f\cos kx ,
\end{equation*}
so that $\nabla^{4}\psi =0$ and

\begin{equation*}
f''''-2k^{2}f''+k^{4}f=0 ,
\end{equation*}
i.e.

\begin{equation*}
f(z)=\bigl(a_{0}+a_{1}z\bigr)\cosh kz+\bigl(b_{0}+b_{1}z\bigr)\sinh kz .
\end{equation*}
With the no slip condition at the free surface $u_{x}(0)=0$

\begin{equation*}
f'(0)=0\iff a_{1}+k b_{0}=0 ,
\end{equation*}
and for a material surface $u_{z}=0$ on the two impermeable
boundaries

\begin{equation*}
f(0)=0,\qquad f(h)=0 ,
\end{equation*}
we may put $a_{0}=0,\;b_{0}=-a_{1}/k$.  The shear stress
$\sigma_{xz}=\mu\,(f''+k^{2}f)\sin kx$ at $z=h$ is

\begin{equation*}
\mu\,{\cal L}f(h)=\mu \,2k\Big[\cosh kh\,(k a_{1}h+b_{1})
+\sinh kh\,k h b_{1}\Big]=S_{0} ,
\tag{1}
\end{equation*}
with ${\cal L}f=f''+k^{2}f$.  The condition $f(h)=0$ gives

\begin{equation*}
a_{1}h\cosh kh+\Big(b_{0}+b_{1}h\Big)\sinh kh=0 ,
\tag{2}
\end{equation*}
and (1)-(2) determine $a_{1}$ and $b_{1}$,

\begin{equation*}
a_{1}=-
\frac{S_{0}h\sinh kh}{2\mu\big[\,k h-\sinh kh\cosh kh\,\big]}\;,
\qquad 
b_{1}=a_{1}\,\frac{\,1-k h\coth kh\,}{k h}\; .
\end{equation*}
With $p=\mu k^{-1}\big(k^{2}f'-f'''\big)\cos kx+g_{0}$ the $zz$ stress
is

\begin{equation*}
\sigma_{zz}=\Big[-3\mu k f'+\mu k^{-1}f'''\Big]\cos kx-g_{0},
\end{equation*}
so that $\sigma_{zz}(h)=0$ gives $g_{0}=-3\mu k f'(h)+\mu k^{-1}
f'''(h)$ and

\begin{equation*}
\rho g e_{s}=
-3\mu k\big[f'(0)-f'(h)\big]+\mu k^{-1}\big[f'''(0)-f'''(h)\big] .
\end{equation*}
With $f'(0)=0$ this gives, on using (1)-(2),

\begin{equation*}
\rho g e_{s}=2\mu k a_{1}\Big[\,1-\frac{k h}{\sinh kh}\,\Big]
     =S_{0}\,
\frac{k h\big(k h-\sinh kh\big)}{k h-\sinh kh\cosh kh}\;,
\end{equation*}
i.e. with the sign convention $\sigma_{zz}=+\Delta\rho g e\cos kx$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\chi(kh),\qquad 
\chi(kh)=
\frac{kh\big[\sinh kh-kh\big]}{\sinh kh\cosh kh-kh}
     =\frac{2kh\big[\sinh kh-kh\big]}{\sinh2kh-2kh}>0,
\end{equation*}
which is the usual viscous-sheet response function.  In particular

\begin{equation*}
\chi(kh)=\frac{kh\bigl(\sinh kh-kh\bigr)}
               {\tfrac12\sinh2kh-kh}
\end{equation*}
and for the long wave, or thin plate, limit $kh\ll1$

\begin{equation*}
\chi(kh)=\frac{kh}{4}+O\!\big((kh)^{3}\big),
\qquad 
e_{s}\simeq\frac{kh}{4}\,
\frac{S_{0}}{\Delta\rho g},
\end{equation*}
so that the conventional thin–plate numerical factor is
$\chi_{0}=1/4$.  Up to the immaterial factor $\rho/\Delta\rho$ this is
often quoted as

\[
e_{s}\approx \frac{1}{4}\,kh\,\frac{S_{0}}{\Delta\rho g}\;,
\qquad kh\ll1,
\]

i.e. $e_{s}\approx\chi_{0}S_{0}/\Delta\rho g$ with the formal
long–wave constant $\chi_{0}=1/4$.  With the sign convention used
above this is $e_{s}=\chi S_{0}/\rho g$ with
$\chi=kh\,(kh-\sinh kh)/[kh-\sinh kh\cosh kh]$, which is the
$2kh(\sinh kh-kh)/(\sinh2kh-2kh)$ form quoted above.  Putting
$\Delta\rho\simeq\rho$ this is the $\chi$ required in
$e_{s}=\chi S_{0}/\Delta\rho g$.  The $kh\ll1$ limit is the one
commonly quoted as the stable viscous–topographic factor,
$\chi_{0}=1/4$.

6.text:
In the $x\!-\!z$ plane put

\begin{equation*}
u_{x}=f(z)\sin kx,\qquad u_{z}=g(z)\cos kx ,\qquad 
p=P(z)\cos kx , 
\end{equation*}
so that $\nabla\!\cdot\!{\bf u}=0$ gives $g'=-k f$.  With
${\rm \sigma}_{ij}=-p\delta_{ij}+2\mu{\varepsilon}_{ij}$,

\begin{equation*}
\sigma_{xz}=\mu\big(f'-kg\big)\sin kx ,\qquad
\sigma_{zz}=\big[-P+2\mu g'\big]\cos kx ,
\end{equation*}
and

\begin{equation*}
kP+\mu\big(f''-k^{2}f\big)=0 ,\qquad 
-P'+\mu\big(g''-k^{2}g\big)=0 .
\end{equation*}
Putting $C=f'+kg$ one gets $P'=-\mu kC$ and

\begin{equation*}
C''=k^{2}C\qquad\Longrightarrow\qquad C=a\,e^{kz}+b\,e^{-kz}\; .
\end{equation*}
In particular

\begin{equation*}
g''-k^{2}g=-kC
\end{equation*}
gives, up to an additive homogeneous solution,

\begin{equation*}
g=H_{1}e^{kz}+H_{2}e^{-kz}-\frac{a}{2}z e^{kz}
     +\frac{b}{2}z e^{-kz},\qquad 
f=-\frac1k g' .
\end{equation*}
On the free surface $u_{x}(0)=0$ and in the steady state
$u_{z}(0)=0$, so that

\begin{equation*}
f(0)=0\;\;\Longleftrightarrow\; \; -H_{1}+H_{2}+\frac{a-b}{2k}=0,
\qquad g(0)=0\;\;\Longleftrightarrow\;\;H_{1}+H_{2}=0 ,
\end{equation*}
whence
\begin{equation*}
H_{1}=\frac{a-b}{4k},\qquad H_{2}=-H_{1},\qquad
H_{1}-H_{2}=\frac{a-b}{2k} .
\end{equation*}
At the free surface

\begin{equation*}
\sigma_{zz}(0)= \big[-P+2\mu g'\big]_{0}
       =2\mu k\,(H_{1}-H_{2})\cos kx
       =\rho g\,e_{s}\cos kx ,
\end{equation*}
i.e.

\begin{equation*}
\mu\,(a-b)=\rho g\,e_{s},\qquad d:=a-b=\frac{\rho g}{\mu}e_{s} .
\end{equation*}
The zero normal traction at the base, $\sigma_{zz}(h)=0$, is
\begin{equation*}
e^{kh}\!\left[-ha+2H_{1}\right] +
e^{-kh}\!\left[-hb+2H_{1}\right]=0 ,
\end{equation*}
i.e.
\begin{equation*}
d\,(r+1)=2kh\,(ar+b),\qquad r=e^{2kh}.
\end{equation*}
Hence with $d=a-b$

\begin{equation*}
a=\frac{d}{2kh}+\frac{d}{r+1},\qquad 
b=\frac{d}{2kh}-\frac{dr}{r+1},
\qquad 
H_{1}=\frac{d}{4k}.
\end{equation*}
The imposed basal shear is

\begin{equation*}
\mu\big[f'-kg\big]_{h}=S_{0},\qquad
f'-kg=C-2kg .
\end{equation*}
Using the expressions above

\begin{equation*}
\mu\Big\{e^{kh}\!\big[a(1+kh)-2kH_{1}\big]
      +e^{-kh}\!\big[b(1-kh)+2kH_{1}\big]\Big\}=S_{0}
\end{equation*}
and with the values of $a,b,H_{1}$ this reduces to

\begin{equation*}
\mu d\,
\frac{\cosh^{2}kh+(kh)^{2}}{kh\cosh kh}=S_{0} .
\end{equation*}
Since $\mu d=\rho g e_{s}$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\;
      \frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}} ,
\end{equation*}
i.e. with the usual buoyancy $\Delta\rho g$

\begin{equation*}
e_{s}= \chi\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi(kh)=\frac{kh\,\cosh kh}{\cosh^{2}kh+(kh)^{2}}
       =\frac{1}{\displaystyle\frac{\cosh kh}{kh}
          +\frac{kh}{\cosh kh}} .
\end{equation*}
In particular $ \chi\approx kh$ for $kh\ll1$ and
$\chi\sim2kh\,e^{-kh}$ for $kh\gg1$.
If the normal traction at the free surface is written with the
plate density $\rho$ this is $e_{s}= \chi S_{0}/\rho g$; with the
conventional buoyancy $\Delta\rho g$ the same dimensionless
function is obtained with $\rho\to\Delta\rho$.  Up to the
conventional $\rho\leftrightarrow\Delta\rho$ identification this is
the often quoted

\[
e_{s}\approx\frac{S_{0}}{\Delta\rho g}\,
\frac{kh}{\,1+(kh)^{2}\,} \qquad kh\ll1,
\]

the exact steady Stokes result being the $kh\cosh kh/[\cosh^{2}kh+(kh)^{2}]$
form above.  This is the $kh\cosh kh/[\cosh^{2}kh+(kh)^{2}]$ factor,
often written in the equivalent form $\chi=kh\cosh kh/
\big[\cosh^{2}kh+(kh)^{2}\big]$, which for $kh\ll1$ reduces to the
familiar $\chi\simeq kh$.  With the density $\rho$ used in the
$\sigma_{zz}$ condition the same $\chi$ gives $e_{s}=\chi S_{0}/\rho g$,
i.e. $e_{s}=\chi S_{0}/\Delta\rho g$ after the replacement
$\rho\to\Delta\rho$. ∎

11.text:
In the Stokes approximation with $u_{x}=f(z)\sin kx$, $u_{z}=g(z)\cos kx$,
$\nabla\!\cdot u=0$ gives $g'=-k f$ and

\begin{equation*}
(k^{2}-\partial_{z}^{2})^{2}g=0 , \qquad 
p_{1}= \frac{\mu}{k^{2}}\Big(g'''-k^{2}g'\Big) .
\end{equation*}

With $g(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$

\begin{equation*}
\sigma_{zz}=-p_{1}+2\mu g'=
2\mu k\Big[(A+Bz)e^{kz}-(C+Dz)e^{-kz}\Big]\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=-\frac{\mu}{k}\big(g''+k^{2}g\big)\sin kx .
\end{equation*}
On the free surface $u_{x}=0$, i.e. $g'(0)=0$, and for a
time independent topography $u_{z}(0)=0$, $g(0)=0$.  Hence

\begin{equation*}
C=-A,\qquad B+D=-2kA,
\end{equation*}
and
\begin{equation*}
\sigma_{zz}(0)=\rho g e\cos kx=4\mu kA\cos kx ,
\qquad A=\frac{\rho ge}{4\mu k} .
\end{equation*}
The zero normal stress at the base,
$\sigma_{zz}(h)=0$, is

\begin{equation*}
(A+Bh)e^{kh}=(C+Dh)e^{-kh},
\end{equation*}
i.e. 

\begin{equation*}
B=-\frac{A\big[e^{2kh}+1+2kh\big]}{h\big[e^{2kh}+1\big]},\qquad
D=\frac A h-\frac{2kA\,e^{2kh}}{e^{2kh}+1}\; .
\end{equation*}
The basal shear

\begin{equation*}
\sigma_{xz}(h)=\mu\Big[f'-kg\Big]_{h}=S_{0}\sin kx ,
\qquad
f' -kg =-\frac{g''+k^{2}g}{k} ,
\end{equation*}
gives on the base

\begin{equation*}
A\Big[(e^{2kh}+1)^{2}+4k^{2}h^{2}e^{2kh}\Big]
     =\frac{S_{0}}{2\mu}\;h\,(e^{2kh}+1)e^{kh}.
\end{equation*}
With $x=kh$ and $E=e^{x}$

\begin{equation*}
A=\frac{S_{0}h}{2\mu}\,
\frac{E\big(E^{2}+1\big)}{\big(E^{2}+1\big)^{2}+4x^{2}E^{2}} .
\end{equation*}
Using $A=\rho g e/4\mu k$ the steady, i.e. $e_{s}$, topography is

\begin{equation*}
e_{s}
 =\frac{S_{0}}{\rho g}\,
   \frac{2xE\big(E^{2}+1\big)}
        {\big(E^{2}+1\big)^{2}+4x^{2}E^{2}}
 =\frac{S_{0}}{\rho g}\,
   \frac{x\cosh x}{\cosh^{2}x+x^{2}}\;,
\end{equation*}
i.e. with the buoyancy $\Delta\rho g$

\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g}, \qquad 
\chi(kh)=\frac{kh\,\cosh kh}{\cosh^{2}kh+(kh)^{2}}
       =\Big[\frac{\cosh kh}{kh}+\frac{kh}{\cosh kh}\Big]^{-1}\!,
\end{equation*}
which is the exact Stokes steady state.  In particular for the
long wave, $kh\ll1$,

\begin{equation*}
\cosh kh=1+\tfrac12(kh)^{2}+O(kh)^{4},
\qquad 
\chi(kh)=kh\Big[1-\tfrac32(kh)^{2}+O(kh)^{4}\Big],
\end{equation*}
so that to leading order

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi_{0}=kh,
\end{equation*}
the familiar $e_{s}\sim h S_{0}/\lambda\Delta\rho g$ scaling.  On the
conventional $kh\sim1$ normalisation this is $e_{s}\approx
0.45\,S_{0}/\Delta\rho g$; with the $kh\ll1$ normalisation the
dimensionless factor is normally quoted as $\chi\approx kh$, i.e.
$e_{s}\approx(kh)S_{0}/\Delta\rho g$, the $2\pi h/\lambda\,S_{0}/
\Delta\rho g$ form used in the geophysical literature.  Replacing
$\rho\to\Delta\rho$ gives the stated $e_{s}=\chi S_{0}/\Delta\rho g$
with the $kh$–dependent factor above, which reduces to the
text-book long-wave limit $\chi\approx kh$. ∎

2.text:
In the linear regime one may write the stream function in the form

\begin{equation*}
\psi(x,z)=f(z)\sin kx\qquad 
u_{x}=\psi_{z}=f'(z)\sin kx,\qquad 
u_{z}=-\psi_{x}=-k f(z)\cos kx ,
\end{equation*}
so that $\nabla^{4}\psi=0$, i.e. $(D^{2}-k^{2})^{2}f=0$.  With the
rigid top $u_{x}(0)=0$ and the kinematic condition $w(0)=\dot e$ one has
for a quasi static flow

\begin{equation*}
f(0)=f'(0)=0 ,
\end{equation*}
and with the normalisation $z$ downwards

\begin{equation*}
f(z)=a\Big[\,z\cosh kz-\frac{\sinh kz}{k}\Big]+b\,z\sinh kz ,
\qquad 
\begin{array}{l}
f'(0)=0\\[2mm]
f'''(0)=2ak^{2}
\end{array}
\end{equation*}
With $p(x,z)=P(z)\cos kx$

\begin{equation*}
P(z)=-\frac{\mu}{k}\Big[f'''(z)-k^{2}f'(z)\Big] ,
\end{equation*}
so that

\begin{equation*}
\sigma_{zz}= -p+2\mu w_{z}=-
\Big[\,P(z)+2\mu k f'(z)\Big]\cos kx .
\end{equation*}
On the free top $ \sigma_{zz}(0)=\rho g e\cos kx$ and $f'(0)=0$ gives

\begin{equation*}
e(t)=\frac{\mu}{k\rho g}f'''(0)=\frac{2\mu k a}{\rho g}\;,
\qquad 
\dot e\,\cos kx=w(0) .
\end{equation*}
At the base $z=h$

\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx=S_{0}\sin kx,
\qquad
\sigma_{zz}(h)=0 .
\end{equation*}
Hence

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0},\qquad 
P(h)+2\mu k f'(h)=0 .
\end{equation*}
With the $f$ above

\begin{equation*}
P(h)+2\mu k f'(h)=0\Longleftrightarrow 
f'''(h)=3k^{2}f'(h)\Longleftrightarrow 
a\big[c_{h}-kh\,s_{h}\big]=kh\,b\,c_{h},
\end{equation*}
where $c_{h}=\cosh kh$, $s_{h}=\sinh kh$, i.e.

\begin{equation*}
b=a\,\frac{1-kh\tanh kh}{kh}\; .
\end{equation*}
Using this in the shear condition

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=2\mu k\,a\,c_{h}
\Big[kh+\frac1{kh}-kh\tanh^{2}kh\Big]=S_{0}
\end{equation*}
gives

\begin{equation*}
a=\frac{S_{0}h\,c_{h}}
{2\mu\big[(kh)^{2}+c_{h}^{2}\big]}\; .
\end{equation*}
The quasi-static surface deflection is therefore

\begin{equation*}
e(t)=\frac{2\mu k a}{\rho g}
     =\frac{S_{0}}{\rho g}\,
       \frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
so that in the steady state $\dot e=0$

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
      {\cal F}(kh),\qquad
{\cal F}(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
the sign being that of $S_{0}$.  In particular for long waves
$kh\ll1$, ${\cal F}\simeq kh$ and

\begin{equation*}
e_{s}\simeq\frac{kh\,S_{0}}{\rho g}\qquad kh\ll1 ,
\end{equation*}
and ${\cal F}\to0$ exponentially for $kh\gg1$.
If the restoring stress is written with the buoyancy contrast
$\Delta\rho$, $\sigma_{zz}^{\rm eff}=\Delta\rho g e\cos kx$, the
formal amplitude

\begin{equation*}
e_{s}= \chi\,\frac{S_{0}}{\Delta\rho g}
\end{equation*}
is obtained with

\begin{equation*}
\chi_{\rho}= {\cal F}(kh)=
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
i.e. up to the conventional $\rho/\Delta\rho$ factor

\[
e_{s}\approx\frac{\rho}{\Delta\rho}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\,
\frac{S_{0}}{\Delta\rho g}\;,
\]

which for the usual geophysical convention $\Delta\rho\simeq\rho$ is
often quoted simply as $\chi={\cal F}(kh)$.  With the sign convention
used above the deflection is $e_{s}=-{\cal F}(kh)S_{0}/\rho g$, the
minus sign expressing the fact that a positive basal traction $\sin kx$
produces a depression $\propto\cos kx$.  In the long–wavelength limit
this is the familiar $e_{s}\simeq kh\,S_{0}/\Delta\rho g$ linear law.
Neglecting the viscous normal stress in $\sigma_{zz}$ the familiar
text-book form $e_{s}= -S_{0}\sinh kh/\big[\rho g\cosh^{2}kh\big]$ is
recovered, i.e. $\chi_{0}= \sinh kh/\cosh^{2}kh$, which reduces to the
same $kh$ small–$kh$ limit. ∎

8.text:
In the $x\!-\!z$ plane put
$\psi(x,z)=\Psi(z)\sin kx$, $u_{x}=\psi_{z}$, $u_{z}=-\psi_{x}$ so that

\begin{equation*}
u_{x}=\Psi^{\prime}\sin kx,\qquad 
u_{z}=-k\Psi\cos kx ,
\end{equation*}
and for a Stokes flow

\begin{equation*}
\nabla^{4}\psi=0\qquad \Longleftrightarrow\qquad 
\Psi''''-2k^{2}\Psi''+k^{4}\Psi=0 ,
\end{equation*}
i.e.

\begin{equation*}
\Psi(z)=\bigl(\alpha_{0}+\alpha_{1}z\bigr)\cosh kz+\bigl(\beta_{0}
+\beta_{1}z\bigr)\sinh kz .
\end{equation*}
On the material top $z=0$

\begin{equation*}
u_{x}(0)=0\;\;\Longleftrightarrow\;\;\Psi'(0)=0 ,\qquad 
u_{z}(0)=\dot e(t)\cos kx\;\;\Longleftrightarrow\;\;\Psi(0)=0 ,
\end{equation*}
so that with the normalisation $\Psi(0)=0$

\begin{equation*}
\alpha_{0}=0,\qquad \beta_{0}=-\frac{\alpha_{1}}{k}, \qquad 
\Psi'(0)=0 .
\end{equation*}
With
$p(x,z)=P(z)\cos kx$,
\begin{equation*}
p(x,z)=-\frac{\mu}{k}\Bigl[\Psi'''-k^{2}\Psi'\Bigr]\cos kx,
\end{equation*}
and

\begin{equation*}
\sigma_{zz}=-p+2\mu u_{z,z}
          =\Bigl[\frac{\mu}{k}\bigl(\Psi'''-k^{2}\Psi'\bigr)
                -2\mu k\Psi' \Bigr]\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\bigl(\Psi''+k^{2}\Psi\bigr)\sin kx .
\end{equation*}
Hence on the free surface, with $\Psi'(0)=0$,

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}\Psi'''(0)\cos kx
           =\rho g\,e(t)\cos kx ,
\end{equation*}
i.e.

\begin{equation*}
\Psi'''(0)=\frac{k\rho g}{\mu}e(t),\qquad 
\Psi'''(0)=2k^{2}\alpha_{1} ,
\end{equation*}
so that

\begin{equation*}
\alpha_{1}= \frac{\rho g}{2\mu k}e(t) .
\end{equation*}
At the base $z=h$

\begin{equation*}
\sigma_{zz}(h)=0\Longleftrightarrow
\Psi'''(h)-3k^{2}\Psi'(h)=0 ,
\end{equation*}
\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx\Longleftrightarrow
\mu\bigl[\Psi''(h)+k^{2}\Psi(h)\bigr]=S_{0}.
\end{equation*}
With $\alpha_{0}=0,\;\beta_{0}=-\alpha_{1}/k$ the two base conditions give

\begin{equation*}
\beta_{1}= \alpha_{1}\,
\frac{\cosh kh-kh\sinh kh}{kh\cosh kh},
\end{equation*}
and

\begin{equation*}
\mu\bigl[\Psi''(h)+k^{2}\Psi(h)\bigr]
      =\frac{2\mu\alpha_{1}}{h\cosh kh}\Bigl[k^{2}h^{2}+\cosh^{2}kh\Bigr]
      =S_{0} .
\end{equation*}
Eliminating $\alpha_{1}$ with $\alpha_{1}= \rho ge/2\mu k$ we obtain the
steady, $\dot e=0$, topographic amplitude

\begin{equation*}
\frac{\rho g}{k}e_{s}
\Bigl[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigr]=S_{0},
\end{equation*}
i.e.

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
     =\frac{S_{0}}{\rho g}\,
\frac{1}{\,kh/\cosh kh+\cosh kh/kh\,}\;,
\end{equation*}
so that in the form $e_{s}=\chi S_{0}/(\Delta\rho g)$ with the
buoyant density $\Delta\rho$ used in $\sigma_{zz}=\Delta\rho g e\cos kx$

\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
       =\Biggl[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Biggr]^{-1},
\end{equation*}
which is the familiar long-wave limit $\chi\sim kh$, $kh\ll1$,
$\chi\sim kh\,e^{-kh}$, $kh\gg1$.  In particular
$e_{s}= \chi S_{0}/\Delta\rho g$ with the $\chi$ above; with the
notation of the statement $\rho\equiv\Delta\rho$ this is
$e_{s}= \chi S_{0}/\rho g$.  For $kh\ll1$,
$\chi\simeq kh/[1+k^{2}h^{2}]$, so that to leading order
$e_{s}\simeq k h S_{0}/\Delta\rho g$, the usual viscous-plate
shear–topography relation. ∎

12.text:
In the linear approximation write

\begin{equation*}
u_{x}=A(z)\sin kx,\qquad u_{z}=B(z)\cos kx,\qquad 
p=P(z)+Q(z)\cos kx ,
\end{equation*}
so that $\nabla\!\cdot\!{\bf u}=0$ gives $B'=-kA$ and

\begin{equation*}
kQ+\mu\bigl(A''-k^{2}A\bigr)=0,\qquad 
Q'=\mu\bigl(B''-k^{2}B\bigr)  ,
\end{equation*}
whence
\begin{equation*}
\bigl(\partial_{z}^{2}-k^{2}\bigr)^{2}B=0 .
\end{equation*}
With the horizontal no– slip condition at the free surface
$A(0)=0$ and the steady kinematic condition $u_{z}(0)=0$ one has

\begin{equation*}
B(0)=0 ,\qquad B'(0)=0 ,\qquad B(z)=a_{2}\sinh kz
        -ka_{2}z\cosh kz+a_{4}z\sinh kz .
\end{equation*}
The normal stress at the free surface is
$\sigma_{zz}=-p+2\mu u_{z,z}= \bigl[-Q+2\mu B'\bigr]\cos kx $,
so that with $\sigma_{zz}(0)=\rho g e\cos kx$

\begin{equation*}
Q(0)=- \rho g e ,\qquad 
k^{2}Q(0)=\mu B'''(0) .
\end{equation*}
Hence on the $ {\rm series}$ $B'''(0)=-2k^{3}a_{2}$,

\begin{equation*}
a_{2}=\frac{\rho g\,e}{2\mu k}\;,
\end{equation*}
and

\begin{equation*}
k^{2}Q=\mu\bigl(B'''-k^{2}B'\bigr) , \qquad 
Q(h)=2\mu B'(h) ,
\end{equation*}
so that at the base

\begin{equation*}
B'''(h)=3k^{2}B'(h) .\tag{1}
\end{equation*}
The basal shear is
$\sigma_{xz}=\mu\bigl(A'-kB\bigr)\sin kx$, i.e.

\begin{equation*}
\sigma_{xz}=-\frac{\mu}{k}\bigl(B''+k^{2}B\bigr)\sin kx ,
\end{equation*}
so that with $\sigma_{xz}(h)=S_{0}\sin kx$,

\begin{equation*}
B''(h)+k^{2}B(h)=-\,\frac{kS_{0}}{\mu}\; . \tag{2}
\end{equation*}
Putting $C_{h}=\cosh kh$, $S_{h}=\sinh kh$ and $\kappa =kh$,

\begin{equation*}
B'(h)=a_{4}\bigl[\kappa C_{h}+S_{h}\bigr]
       -k^{2}a_{2}hS_{h},
\end{equation*}
and (1) gives

\begin{equation*}
a_{4}hC_{h}=a_{2}\!\left[\kappa S_{h}-C_{h}\right], 
\end{equation*}
so that (2) becomes

\begin{equation*}
a_{2}\frac{\kappa^{2}+C_{h}^{2}}{hC_{h}}=\frac{S_{0}}{2\mu}\; .
\end{equation*}
With $a_{2}=\rho g e_{s}/2\mu k$ the viscosity drops out and

\begin{equation*}
\frac{\rho g e_{s}}{k}S_{0}^{-1}
   =\frac{hC_{h}}{\kappa^{2}+C_{h}^{2}},\qquad
e_{s}= \frac{S_{0}}{\rho g}\;
     \frac{\kappa\,C_{h}}{\kappa^{2}+C_{h}^{2}} ,
\end{equation*}
i.e. with $\kappa =kh$

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\;
       \frac{\kappa\cosh\kappa}{\kappa^{2}+\cosh^{2}\kappa}\;,
\qquad 
\chi_{0}(\kappa)=\frac{\kappa\cosh\kappa}{\kappa^{2}+\cosh^{2}\kappa}
 =\Bigl[\frac{\kappa}{\cosh\kappa}+\frac{\cosh\kappa}{\kappa}\Bigr]^{-1} .
\end{equation*}
In particular
$\chi_{0}\approx\kappa$ for $\kappa\ll1$ and
$\chi_{0}\sim4\kappa e^{-\kappa}$ for $\kappa\gg1$.
If the normal stress at the surface is written with the
isostatic density contrast $\Delta\rho$,
$\sigma_{zz}=\Delta\rho\,g\,e\cos kx$, the same calculation gives
the conventional form

\[
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
       \chi(\kappa),\qquad 
\chi(\kappa)=\frac{\kappa\cosh\kappa}{\kappa^{2}+\cosh^{2}\kappa},
\qquad\kappa=k h,
\]

so that on the usual long-wave scale $\kappa\ll1$

\[
e_{s}\simeq \frac{k h}{\Delta\rho g}S_{0},
\]

up to the obvious $\rho\to\Delta\rho$ replacement.  With the
notation $e_{s}=\chi S_{0}/\Delta\rho g$ this is $\chi(\kappa)$ above,
$\chi\to\kappa$ for $kh\ll1$.  The sign is that of $S_{0}$; the
magnitude is the one quoted.  If the $\rho$ appearing in
$\sigma_{zz}= \rho g e\cos kx$ is kept distinct from the
isostatic contrast the familiar result is $e_{s}= (\rho/\Delta\rho)
\chi_{0}S_{0}/\rho g$, i.e. the same dimensionless shape factor
$\chi_{0}(\kappa)$ quoted above.

3.text:
In the linearised Stokes problem write with the stream function
$\psi(x,z)=\Psi(z)\sin kx$,

\begin{equation*}
u_{x}=\Psi'\sin kx ,\qquad u_{z}=-k\Psi\cos kx ,
\end{equation*}
so that $V(z)=-k\Psi(z)$ is the $z$–amplitude of $u_{z}$ and
$U(z)=\Psi'(z)=-V'/k $.  Putting $p=P(z)\cos kx$
\begin{equation*}
kP=\mu\Big[k^{2}\Psi'-\Psi'''\Big],\qquad 
P'=\mu k\Big[k^{2}\Psi-\Psi''\Big] ,
\end{equation*}
so that with $V=-k\Psi$
\begin{equation*}
V^{IV}-2k^{2}V''+k^{4}V=0,\qquad 
V(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}.
\end{equation*}
The stress components are
\begin{equation*}
\sigma_{xz}=\mu\big(\Psi''+k^{2}\Psi\big)\sin kx ,\qquad 
\sigma_{zz}=\Big[-P-2\mu k\Psi'\Big]\cos kx ,
\end{equation*}
and $P=2\mu\big[Be^{kz}+De^{-kz}\big]$.  Hence
\begin{equation*}
\sigma_{zz}=2\mu k\Big[(A+Bz)e^{kz}-(C+Dz)e^{-kz}\Big]\cos kx .
\end{equation*}
The kinematic conditions at the free surface are, to $O(e)$,
$u_{x}(0)=0$, $u_{z}(0)=\dot e$ and for a steady state
$u_{z}(0)=0$.  Thus

\begin{equation*}
V(0)=0,\qquad V'(0)=0 ,
\end{equation*}
i.e. $C=-A$ and $B+D+2kA=0$.  On the free surface
\begin{equation*}
\sigma_{zz}(0)=\rho g\,e\cos kx=-P(0)\cos kx ,
\end{equation*}
so that with $V'(0)=0$
\begin{equation*}
-P(0)=2\mu(B+D)=\rho g e,\qquad 
B+D=-\frac{\rho g e}{2\mu},
\end{equation*}
and $A=\rho g e/4\mu k$.  The lower free surface conditions are
\begin{equation*}
\sigma_{zz}(h)=0\;\;\Longleftrightarrow\;\;
\big(A+Bh\big)e^{kh}=\big(C+Dh\big)e^{-kh},
\end{equation*}
and
\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx\;\;\Longleftrightarrow\;\;
\mu\big(\Psi''+k^{2}\Psi\big)_{h}=S_{0},
\end{equation*}
i.e.
\begin{equation*}
-2\mu\Big[\big(B+kA+kBh\big)e^{kh}
+\big(kC-D+kDh\big)e^{-kh}\Big]=S_{0}.
\end{equation*}
With $C=-A$ and $B+D=-2kA$ the last two conditions give

\begin{equation*}
2\mu A\Big[\,\frac{S}{h}+\frac{4k^{2}h}{S}\Big]=S_{0},
\qquad S=e^{kh}+e^{-kh}=2\cosh kh ,
\end{equation*}
so that with $A=\rho g e/4\mu k$

\begin{equation*}
\frac{\rho g e}{2k}\Big[\frac{S}{h}+\frac{4k^{2}h}{S}\Big]=S_{0} .
\end{equation*}
Hence the steady, stress driven topography is

\begin{equation*}
e_{s}= \frac{2k\,S_{0}}{\rho g}
\frac{hS}{S^{2}+4k^{2}h^{2}}
     =\frac{k h\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}\,
       \frac{S_{0}}{\rho g}\;,
\end{equation*}
in particular
\begin{equation*}
e_{s}= \chi\,\frac{S_{0}}{\rho g},\qquad 
\chi(kh)=\frac{k h\,\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}\;,
\end{equation*}
which is independent of the viscosity.  Putting the isostatic
restoring stress $\Delta\rho g e$ for the overlying air/water,
$\rho\to\Delta\rho$,

\[
e_{s}=\chi\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{k h\cosh kh}{\cosh^{2}kh+(k h)^{2}},
\]

so that for the long wave limit $kh\ll1$,

\[
\chi\simeq k h+O\!\left(k^{3}h^{3}\right),\qquad
e_{s}\simeq k h\,\frac{S_{0}}{\Delta\rho g}\;,
\]

the familiar thin–sheet limit.  With the conventional
isostatic density contrast $\Delta\rho$ the formal factor is the
same with $\rho$ replaced by $\Delta\rho$.  This is the
steady state reached after transients have decayed; the
amplitude is independent of the viscosity $\mu$ and is
normally quoted as $e_{s}\approx kh\,S_{0}/\Delta\rho g$ for
$kh\ll1$.  The $\rho$ in the statement can be identified with the
isostatic contrast $\Delta\rho$.

public_text.4:
For the Stokes flow write the stream function

\begin{equation*}
\psi (x,z)=f(z)\sin kx\qquad 
u_{x}=\psi_{z}=f'\sin kx\,,\qquad 
u_{z}=-\psi_{x}=-k f\cos kx ,
\end{equation*}
so that $\nabla^{4}\psi =0$ and

\begin{equation*}
f''''-2k^{2}f''+k^{4}f=0 ,
\end{equation*}
i.e.

\begin{equation*}
f(z)=\bigl(a_{0}+a_{1}z\bigr)\cosh kz+\bigl(b_{0}+b_{1}z\bigr)\sinh kz .
\end{equation*}
With the no slip condition at the free surface $u_{x}(0)=0$

\begin{equation*}
f'(0)=0\iff a_{1}+k b_{0}=0 ,
\end{equation*}
and for a material surface $u_{z}=0$ on the two impermeable
boundaries

\begin{equation*}
f(0)=0,\qquad f(h)=0 ,
\end{equation*}
we may put $a_{0}=0,\;b_{0}=-a_{1}/k$.  The shear stress
$\sigma_{xz}=\mu\,(f''+k^{2}f)\sin kx$ at $z=h$ is

\begin{equation*}
\mu\,{\cal L}f(h)=\mu \,2k\Big[\cosh kh\,(k a_{1}h+b_{1})
+\sinh kh\,k h b_{1}\Big]=S_{0} ,
\tag{1}
\end{equation*}
with ${\cal L}f=f''+k^{2}f$.  The condition $f(h)=0$ gives

\begin{equation*}
a_{1}h\cosh kh+\Big(b_{0}+b_{1}h\Big)\sinh kh=0 ,
\tag{2}
\end{equation*}
and (1)-(2) determine $a_{1}$ and $b_{1}$,

\begin{equation*}
a_{1}=-
\frac{S_{0}h\sinh kh}{2\mu\big[\,k h-\sinh kh\cosh kh\,\big]}\;,
\qquad 
b_{1}=a_{1}\,\frac{\,1-k h\coth kh\,}{k h}\; .
\end{equation*}
With $p=\mu k^{-1}\big(k^{2}f'-f'''\big)\cos kx+g_{0}$ the $zz$ stress
is

\begin{equation*}
\sigma_{zz}=\Big[-3\mu k f'+\mu k^{-1}f'''\Big]\cos kx-g_{0},
\end{equation*}
so that $\sigma_{zz}(h)=0$ gives $g_{0}=-3\mu k f'(h)+\mu k^{-1}
f'''(h)$ and

\begin{equation*}
\rho g e_{s}=
-3\mu k\big[f'(0)-f'(h)\big]+\mu k^{-1}\big[f'''(0)-f'''(h)\big] .
\end{equation*}
With $f'(0)=0$ this gives, on using (1)-(2),

\begin{equation*}
\rho g e_{s}=2\mu k a_{1}\Big[\,1-\frac{k h}{\sinh kh}\,\Big]
     =S_{0}\,
\frac{k h\big(k h-\sinh kh\big)}{k h-\sinh kh\cosh kh}\;,
\end{equation*}
i.e. with the sign convention $\sigma_{zz}=+\Delta\rho g e\cos kx$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\chi(kh),\qquad 
\chi(kh)=
\frac{kh\big[\sinh kh-kh\big]}{\sinh kh\cosh kh-kh}
     =\frac{2kh\big[\sinh kh-kh\big]}{\sinh2kh-2kh}>0,
\end{equation*}
which is the usual viscous-sheet response function.  In particular

\begin{equation*}
\chi(kh)=\frac{kh\bigl(\sinh kh-kh\bigr)}
               {\tfrac12\sinh2kh-kh}
\end{equation*}
and for the long wave, or thin plate, limit $kh\ll1$

\begin{equation*}
\chi(kh)=\frac{kh}{4}+O\!\big((kh)^{3}\big),
\qquad 
e_{s}\simeq\frac{kh}{4}\,
\frac{S_{0}}{\Delta\rho g},
\end{equation*}
so that the conventional thin–plate numerical factor is
$\chi_{0}=1/4$.  Up to the immaterial factor $\rho/\Delta\rho$ this is
often quoted as

\[
e_{s}\approx \frac{1}{4}\,kh\,\frac{S_{0}}{\Delta\rho g}\;,
\qquad kh\ll1,
\]

i.e. $e_{s}\approx\chi_{0}S_{0}/\Delta\rho g$ with the formal
long–wave constant $\chi_{0}=1/4$.  With the sign convention used
above this is $e_{s}=\chi S_{0}/\rho g$ with
$\chi=kh\,(kh-\sinh kh)/[kh-\sinh kh\cosh kh]$, which is the
$2kh(\sinh kh-kh)/(\sinh2kh-2kh)$ form quoted above.  Putting
$\Delta\rho\simeq\rho$ this is the $\chi$ required in
$e_{s}=\chi S_{0}/\Delta\rho g$.  The $kh\ll1$ limit is the one
commonly quoted as the stable viscous–topographic factor,
$\chi_{0}=1/4$.

public_text.6:
In the $x\!-\!z$ plane put

\begin{equation*}
u_{x}=f(z)\sin kx,\qquad u_{z}=g(z)\cos kx ,\qquad 
p=P(z)\cos kx , 
\end{equation*}
so that $\nabla\!\cdot\!{\bf u}=0$ gives $g'=-k f$.  With
${\rm \sigma}_{ij}=-p\delta_{ij}+2\mu{\varepsilon}_{ij}$,

\begin{equation*}
\sigma_{xz}=\mu\big(f'-kg\big)\sin kx ,\qquad
\sigma_{zz}=\big[-P+2\mu g'\big]\cos kx ,
\end{equation*}
and

\begin{equation*}
kP+\mu\big(f''-k^{2}f\big)=0 ,\qquad 
-P'+\mu\big(g''-k^{2}g\big)=0 .
\end{equation*}
Putting $C=f'+kg$ one gets $P'=-\mu kC$ and

\begin{equation*}
C''=k^{2}C\qquad\Longrightarrow\qquad C=a\,e^{kz}+b\,e^{-kz}\; .
\end{equation*}
In particular

\begin{equation*}
g''-k^{2}g=-kC
\end{equation*}
gives, up to an additive homogeneous solution,

\begin{equation*}
g=H_{1}e^{kz}+H_{2}e^{-kz}-\frac{a}{2}z e^{kz}
     +\frac{b}{2}z e^{-kz},\qquad 
f=-\frac1k g' .
\end{equation*}
On the free surface $u_{x}(0)=0$ and in the steady state
$u_{z}(0)=0$, so that

\begin{equation*}
f(0)=0\;\;\Longleftrightarrow\; \; -H_{1}+H_{2}+\frac{a-b}{2k}=0,
\qquad g(0)=0\;\;\Longleftrightarrow\;\;H_{1}+H_{2}=0 ,
\end{equation*}
whence
\begin{equation*}
H_{1}=\frac{a-b}{4k},\qquad H_{2}=-H_{1},\qquad
H_{1}-H_{2}=\frac{a-b}{2k} .
\end{equation*}
At the free surface

\begin{equation*}
\sigma_{zz}(0)= \big[-P+2\mu g'\big]_{0}
       =2\mu k\,(H_{1}-H_{2})\cos kx
       =\rho g\,e_{s}\cos kx ,
\end{equation*}
i.e.

\begin{equation*}
\mu\,(a-b)=\rho g\,e_{s},\qquad d:=a-b=\frac{\rho g}{\mu}e_{s} .
\end{equation*}
The zero normal traction at the base, $\sigma_{zz}(h)=0$, is
\begin{equation*}
e^{kh}\!\left[-ha+2H_{1}\right] +
e^{-kh}\!\left[-hb+2H_{1}\right]=0 ,
\end{equation*}
i.e.
\begin{equation*}
d\,(r+1)=2kh\,(ar+b),\qquad r=e^{2kh}.
\end{equation*}
Hence with $d=a-b$

\begin{equation*}
a=\frac{d}{2kh}+\frac{d}{r+1},\qquad 
b=\frac{d}{2kh}-\frac{dr}{r+1},
\qquad 
H_{1}=\frac{d}{4k}.
\end{equation*}
The imposed basal shear is

\begin{equation*}
\mu\big[f'-kg\big]_{h}=S_{0},\qquad
f'-kg=C-2kg .
\end{equation*}
Using the expressions above

\begin{equation*}
\mu\Big\{e^{kh}\!\big[a(1+kh)-2kH_{1}\big]
      +e^{-kh}\!\big[b(1-kh)+2kH_{1}\big]\Big\}=S_{0}
\end{equation*}
and with the values of $a,b,H_{1}$ this reduces to

\begin{equation*}
\mu d\,
\frac{\cosh^{2}kh+(kh)^{2}}{kh\cosh kh}=S_{0} .
\end{equation*}
Since $\mu d=\rho g e_{s}$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\;
      \frac{kh\cosh kh}{\cosh^{2}kh+(kh)^{2}} ,
\end{equation*}
i.e. with the usual buoyancy $\Delta\rho g$

\begin{equation*}
e_{s}= \chi\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi(kh)=\frac{kh\,\cosh kh}{\cosh^{2}kh+(kh)^{2}}
       =\frac{1}{\displaystyle\frac{\cosh kh}{kh}
          +\frac{kh}{\cosh kh}} .
\end{equation*}
In particular $ \chi\approx kh$ for $kh\ll1$ and
$\chi\sim2kh\,e^{-kh}$ for $kh\gg1$.
If the normal traction at the free surface is written with the
plate density $\rho$ this is $e_{s}= \chi S_{0}/\rho g$; with the
conventional buoyancy $\Delta\rho g$ the same dimensionless
function is obtained with $\rho\to\Delta\rho$.  Up to the
conventional $\rho\leftrightarrow\Delta\rho$ identification this is
the often quoted

\[
e_{s}\approx\frac{S_{0}}{\Delta\rho g}\,
\frac{kh}{\,1+(kh)^{2}\,} \qquad kh\ll1,
\]

the exact steady Stokes result being the $kh\cosh kh/[\cosh^{2}kh+(kh)^{2}]$
form above.  This is the $kh\cosh kh/[\cosh^{2}kh+(kh)^{2}]$ factor,
often written in the equivalent form $\chi=kh\cosh kh/
\big[\cosh^{2}kh+(kh)^{2}\big]$, which for $kh\ll1$ reduces to the
familiar $\chi\simeq kh$.  With the density $\rho$ used in the
$\sigma_{zz}$ condition the same $\chi$ gives $e_{s}=\chi S_{0}/\rho g$,
i.e. $e_{s}=\chi S_{0}/\Delta\rho g$ after the replacement
$\rho\to\Delta\rho$. ∎

public_text.11:
In the Stokes approximation with $u_{x}=f(z)\sin kx$, $u_{z}=g(z)\cos kx$,
$\nabla\!\cdot u=0$ gives $g'=-k f$ and

\begin{equation*}
(k^{2}-\partial_{z}^{2})^{2}g=0 , \qquad 
p_{1}= \frac{\mu}{k^{2}}\Big(g'''-k^{2}g'\Big) .
\end{equation*}

With $g(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$

\begin{equation*}
\sigma_{zz}=-p_{1}+2\mu g'=
2\mu k\Big[(A+Bz)e^{kz}-(C+Dz)e^{-kz}\Big]\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=-\frac{\mu}{k}\big(g''+k^{2}g\big)\sin kx .
\end{equation*}
On the free surface $u_{x}=0$, i.e. $g'(0)=0$, and for a
time independent topography $u_{z}(0)=0$, $g(0)=0$.  Hence

\begin{equation*}
C=-A,\qquad B+D=-2kA,
\end{equation*}
and
\begin{equation*}
\sigma_{zz}(0)=\rho g e\cos kx=4\mu kA\cos kx ,
\qquad A=\frac{\rho ge}{4\mu k} .
\end{equation*}
The zero normal stress at the base,
$\sigma_{zz}(h)=0$, is

\begin{equation*}
(A+Bh)e^{kh}=(C+Dh)e^{-kh},
\end{equation*}
i.e. 

\begin{equation*}
B=-\frac{A\big[e^{2kh}+1+2kh\big]}{h\big[e^{2kh}+1\big]},\qquad
D=\frac A h-\frac{2kA\,e^{2kh}}{e^{2kh}+1}\; .
\end{equation*}
The basal shear

\begin{equation*}
\sigma_{xz}(h)=\mu\Big[f'-kg\Big]_{h}=S_{0}\sin kx ,
\qquad
f' -kg =-\frac{g''+k^{2}g}{k} ,
\end{equation*}
gives on the base

\begin{equation*}
A\Big[(e^{2kh}+1)^{2}+4k^{2}h^{2}e^{2kh}\Big]
     =\frac{S_{0}}{2\mu}\;h\,(e^{2kh}+1)e^{kh}.
\end{equation*}
With $x=kh$ and $E=e^{x}$

\begin{equation*}
A=\frac{S_{0}h}{2\mu}\,
\frac{E\big(E^{2}+1\big)}{\big(E^{2}+1\big)^{2}+4x^{2}E^{2}} .
\end{equation*}
Using $A=\rho g e/4\mu k$ the steady, i.e. $e_{s}$, topography is

\begin{equation*}
e_{s}
 =\frac{S_{0}}{\rho g}\,
   \frac{2xE\big(E^{2}+1\big)}
        {\big(E^{2}+1\big)^{2}+4x^{2}E^{2}}
 =\frac{S_{0}}{\rho g}\,
   \frac{x\cosh x}{\cosh^{2}x+x^{2}}\;,
\end{equation*}
i.e. with the buoyancy $\Delta\rho g$

\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g}, \qquad 
\chi(kh)=\frac{kh\,\cosh kh}{\cosh^{2}kh+(kh)^{2}}
       =\Big[\frac{\cosh kh}{kh}+\frac{kh}{\cosh kh}\Big]^{-1}\!,
\end{equation*}
which is the exact Stokes steady state.  In particular for the
long wave, $kh\ll1$,

\begin{equation*}
\cosh kh=1+\tfrac12(kh)^{2}+O(kh)^{4},
\qquad 
\chi(kh)=kh\Big[1-\tfrac32(kh)^{2}+O(kh)^{4}\Big],
\end{equation*}
so that to leading order

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi_{0}=kh,
\end{equation*}
the familiar $e_{s}\sim h S_{0}/\lambda\Delta\rho g$ scaling.  On the
conventional $kh\sim1$ normalisation this is $e_{s}\approx
0.45\,S_{0}/\Delta\rho g$; with the $kh\ll1$ normalisation the
dimensionless factor is normally quoted as $\chi\approx kh$, i.e.
$e_{s}\approx(kh)S_{0}/\Delta\rho g$, the $2\pi h/\lambda\,S_{0}/
\Delta\rho g$ form used in the geophysical literature.  Replacing
$\rho\to\Delta\rho$ gives the stated $e_{s}=\chi S_{0}/\Delta\rho g$
with the $kh$–dependent factor above, which reduces to the
text-book long-wave limit $\chi\approx kh$. ∎

public_text.2:
In the linear regime one may write the stream function in the form

\begin{equation*}
\psi(x,z)=f(z)\sin kx\qquad 
u_{x}=\psi_{z}=f'(z)\sin kx,\qquad 
u_{z}=-\psi_{x}=-k f(z)\cos kx ,
\end{equation*}
so that $\nabla^{4}\psi=0$, i.e. $(D^{2}-k^{2})^{2}f=0$.  With the
rigid top $u_{x}(0)=0$ and the kinematic condition $w(0)=\dot e$ one has
for a quasi static flow

\begin{equation*}
f(0)=f'(0)=0 ,
\end{equation*}
and with the normalisation $z$ downwards

\begin{equation*}
f(z)=a\Big[\,z\cosh kz-\frac{\sinh kz}{k}\Big]+b\,z\sinh kz ,
\qquad 
\begin{array}{l}
f'(0)=0\\[2mm]
f'''(0)=2ak^{2}
\end{array}
\end{equation*}
With $p(x,z)=P(z)\cos kx$

\begin{equation*}
P(z)=-\frac{\mu}{k}\Big[f'''(z)-k^{2}f'(z)\Big] ,
\end{equation*}
so that

\begin{equation*}
\sigma_{zz}= -p+2\mu w_{z}=-
\Big[\,P(z)+2\mu k f'(z)\Big]\cos kx .
\end{equation*}
On the free top $ \sigma_{zz}(0)=\rho g e\cos kx$ and $f'(0)=0$ gives

\begin{equation*}
e(t)=\frac{\mu}{k\rho g}f'''(0)=\frac{2\mu k a}{\rho g}\;,
\qquad 
\dot e\,\cos kx=w(0) .
\end{equation*}
At the base $z=h$

\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx=S_{0}\sin kx,
\qquad
\sigma_{zz}(h)=0 .
\end{equation*}
Hence

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0},\qquad 
P(h)+2\mu k f'(h)=0 .
\end{equation*}
With the $f$ above

\begin{equation*}
P(h)+2\mu k f'(h)=0\Longleftrightarrow 
f'''(h)=3k^{2}f'(h)\Longleftrightarrow 
a\big[c_{h}-kh\,s_{h}\big]=kh\,b\,c_{h},
\end{equation*}
where $c_{h}=\cosh kh$, $s_{h}=\sinh kh$, i.e.

\begin{equation*}
b=a\,\frac{1-kh\tanh kh}{kh}\; .
\end{equation*}
Using this in the shear condition

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=2\mu k\,a\,c_{h}
\Big[kh+\frac1{kh}-kh\tanh^{2}kh\Big]=S_{0}
\end{equation*}
gives

\begin{equation*}
a=\frac{S_{0}h\,c_{h}}
{2\mu\big[(kh)^{2}+c_{h}^{2}\big]}\; .
\end{equation*}
The quasi-static surface deflection is therefore

\begin{equation*}
e(t)=\frac{2\mu k a}{\rho g}
     =\frac{S_{0}}{\rho g}\,
       \frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
so that in the steady state $\dot e=0$

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
      {\cal F}(kh),\qquad
{\cal F}(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
the sign being that of $S_{0}$.  In particular for long waves
$kh\ll1$, ${\cal F}\simeq kh$ and

\begin{equation*}
e_{s}\simeq\frac{kh\,S_{0}}{\rho g}\qquad kh\ll1 ,
\end{equation*}
and ${\cal F}\to0$ exponentially for $kh\gg1$.
If the restoring stress is written with the buoyancy contrast
$\Delta\rho$, $\sigma_{zz}^{\rm eff}=\Delta\rho g e\cos kx$, the
formal amplitude

\begin{equation*}
e_{s}= \chi\,\frac{S_{0}}{\Delta\rho g}
\end{equation*}
is obtained with

\begin{equation*}
\chi_{\rho}= {\cal F}(kh)=
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
i.e. up to the conventional $\rho/\Delta\rho$ factor

\[
e_{s}\approx\frac{\rho}{\Delta\rho}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\,
\frac{S_{0}}{\Delta\rho g}\;,
\]

which for the usual geophysical convention $\Delta\rho\simeq\rho$ is
often quoted simply as $\chi={\cal F}(kh)$.  With the sign convention
used above the deflection is $e_{s}=-{\cal F}(kh)S_{0}/\rho g$, the
minus sign expressing the fact that a positive basal traction $\sin kx$
produces a depression $\propto\cos kx$.  In the long–wavelength limit
this is the familiar $e_{s}\simeq kh\,S_{0}/\Delta\rho g$ linear law.
Neglecting the viscous normal stress in $\sigma_{zz}$ the familiar
text-book form $e_{s}= -S_{0}\sinh kh/\big[\rho g\cosh^{2}kh\big]$ is
recovered, i.e. $\chi_{0}= \sinh kh/\cosh^{2}kh$, which reduces to the
same $kh$ small–$kh$ limit. ∎

public_text.8:
In the $x\!-\!z$ plane put
$\psi(x,z)=\Psi(z)\sin kx$, $u_{x}=\psi_{z}$, $u_{z}=-\psi_{x}$ so that

\begin{equation*}
u_{x}=\Psi^{\prime}\sin kx,\qquad 
u_{z}=-k\Psi\cos kx ,
\end{equation*}
and for a Stokes flow

\begin{equation*}
\nabla^{4}\psi=0\qquad \Longleftrightarrow\qquad 
\Psi''''-2k^{2}\Psi''+k^{4}\Psi=0 ,
\end{equation*}
i.e.

\begin{equation*}
\Psi(z)=\bigl(\alpha_{0}+\alpha_{1}z\bigr)\cosh kz+\bigl(\beta_{0}
+\beta_{1}z\bigr)\sinh kz .
\end{equation*}
On the material top $z=0$

\begin{equation*}
u_{x}(0)=0\;\;\Longleftrightarrow\;\;\Psi'(0)=0 ,\qquad 
u_{z}(0)=\dot e(t)\cos kx\;\;\Longleftrightarrow\;\;\Psi(0)=0 ,
\end{equation*}
so that with the normalisation $\Psi(0)=0$

\begin{equation*}
\alpha_{0}=0,\qquad \beta_{0}=-\frac{\alpha_{1}}{k}, \qquad 
\Psi'(0)=0 .
\end{equation*}
With
$p(x,z)=P(z)\cos kx$,
\begin{equation*}
p(x,z)=-\frac{\mu}{k}\Bigl[\Psi'''-k^{2}\Psi'\Bigr]\cos kx,
\end{equation*}
and

\begin{equation*}
\sigma_{zz}=-p+2\mu u_{z,z}
          =\Bigl[\frac{\mu}{k}\bigl(\Psi'''-k^{2}\Psi'\bigr)
                -2\mu k\Psi' \Bigr]\cos kx ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\bigl(\Psi''+k^{2}\Psi\bigr)\sin kx .
\end{equation*}
Hence on the free surface, with $\Psi'(0)=0$,

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}\Psi'''(0)\cos kx
           =\rho g\,e(t)\cos kx ,
\end{equation*}
i.e.

\begin{equation*}
\Psi'''(0)=\frac{k\rho g}{\mu}e(t),\qquad 
\Psi'''(0)=2k^{2}\alpha_{1} ,
\end{equation*}
so that

\begin{equation*}
\alpha_{1}= \frac{\rho g}{2\mu k}e(t) .
\end{equation*}
At the base $z=h$

\begin{equation*}
\sigma_{zz}(h)=0\Longleftrightarrow
\Psi'''(h)-3k^{2}\Psi'(h)=0 ,
\end{equation*}
\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx\Longleftrightarrow
\mu\bigl[\Psi''(h)+k^{2}\Psi(h)\bigr]=S_{0}.
\end{equation*}
With $\alpha_{0}=0,\;\beta_{0}=-\alpha_{1}/k$ the two base conditions give

\begin{equation*}
\beta_{1}= \alpha_{1}\,
\frac{\cosh kh-kh\sinh kh}{kh\cosh kh},
\end{equation*}
and

\begin{equation*}
\mu\bigl[\Psi''(h)+k^{2}\Psi(h)\bigr]
      =\frac{2\mu\alpha_{1}}{h\cosh kh}\Bigl[k^{2}h^{2}+\cosh^{2}kh\Bigr]
      =S_{0} .
\end{equation*}
Eliminating $\alpha_{1}$ with $\alpha_{1}= \rho ge/2\mu k$ we obtain the
steady, $\dot e=0$, topographic amplitude

\begin{equation*}
\frac{\rho g}{k}e_{s}
\Bigl[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigr]=S_{0},
\end{equation*}
i.e.

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
     =\frac{S_{0}}{\rho g}\,
\frac{1}{\,kh/\cosh kh+\cosh kh/kh\,}\;,
\end{equation*}
so that in the form $e_{s}=\chi S_{0}/(\Delta\rho g)$ with the
buoyant density $\Delta\rho$ used in $\sigma_{zz}=\Delta\rho g e\cos kx$

\begin{equation*}
\chi(kh)=\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh}
       =\Biggl[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Biggr]^{-1},
\end{equation*}
which is the familiar long-wave limit $\chi\sim kh$, $kh\ll1$,
$\chi\sim kh\,e^{-kh}$, $kh\gg1$.  In particular
$e_{s}= \chi S_{0}/\Delta\rho g$ with the $\chi$ above; with the
notation of the statement $\rho\equiv\Delta\rho$ this is
$e_{s}= \chi S_{0}/\rho g$.  For $kh\ll1$,
$\chi\simeq kh/[1+k^{2}h^{2}]$, so that to leading order
$e_{s}\simeq k h S_{0}/\Delta\rho g$, the usual viscous-plate
shear–topography relation. ∎

public_text.12:
In the linear approximation write

\begin{equation*}
u_{x}=A(z)\sin kx,\qquad u_{z}=B(z)\cos kx,\qquad 
p=P(z)+Q(z)\cos kx ,
\end{equation*}
so that $\nabla\!\cdot\!{\bf u}=0$ gives $B'=-kA$ and

\begin{equation*}
kQ+\mu\bigl(A''-k^{2}A\bigr)=0,\qquad 
Q'=\mu\bigl(B''-k^{2}B\bigr)  ,
\end{equation*}
whence
\begin{equation*}
\bigl(\partial_{z}^{2}-k^{2}\bigr)^{2}B=0 .
\end{equation*}
With the horizontal no– slip condition at the free surface
$A(0)=0$ and the steady kinematic condition $u_{z}(0)=0$ one has

\begin{equation*}
B(0)=0 ,\qquad B'(0)=0 ,\qquad B(z)=a_{2}\sinh kz
        -ka_{2}z\cosh kz+a_{4}z\sinh kz .
\end{equation*}
The normal stress at the free surface is
$\sigma_{zz}=-p+2\mu u_{z,z}= \bigl[-Q+2\mu B'\bigr]\cos kx $,
so that with $\sigma_{zz}(0)=\rho g e\cos kx$

\begin{equation*}
Q(0)=- \rho g e ,\qquad 
k^{2}Q(0)=\mu B'''(0) .
\end{equation*}
Hence on the $ {\rm series}$ $B'''(0)=-2k^{3}a_{2}$,

\begin{equation*}
a_{2}=\frac{\rho g\,e}{2\mu k}\;,
\end{equation*}
and

\begin{equation*}
k^{2}Q=\mu\bigl(B'''-k^{2}B'\bigr) , \qquad 
Q(h)=2\mu B'(h) ,
\end{equation*}
so that at the base

\begin{equation*}
B'''(h)=3k^{2}B'(h) .\tag{1}
\end{equation*}
The basal shear is
$\sigma_{xz}=\mu\bigl(A'-kB\bigr)\sin kx$, i.e.

\begin{equation*}
\sigma_{xz}=-\frac{\mu}{k}\bigl(B''+k^{2}B\bigr)\sin kx ,
\end{equation*}
so that with $\sigma_{xz}(h)=S_{0}\sin kx$,

\begin{equation*}
B''(h)+k^{2}B(h)=-\,\frac{kS_{0}}{\mu}\; . \tag{2}
\end{equation*}
Putting $C_{h}=\cosh kh$, $S_{h}=\sinh kh$ and $\kappa =kh$,

\begin{equation*}
B'(h)=a_{4}\bigl[\kappa C_{h}+S_{h}\bigr]
       -k^{2}a_{2}hS_{h},
\end{equation*}
and (1) gives

\begin{equation*}
a_{4}hC_{h}=a_{2}\!\left[\kappa S_{h}-C_{h}\right], 
\end{equation*}
so that (2) becomes

\begin{equation*}
a_{2}\frac{\kappa^{2}+C_{h}^{2}}{hC_{h}}=\frac{S_{0}}{2\mu}\; .
\end{equation*}
With $a_{2}=\rho g e_{s}/2\mu k$ the viscosity drops out and

\begin{equation*}
\frac{\rho g e_{s}}{k}S_{0}^{-1}
   =\frac{hC_{h}}{\kappa^{2}+C_{h}^{2}},\qquad
e_{s}= \frac{S_{0}}{\rho g}\;
     \frac{\kappa\,C_{h}}{\kappa^{2}+C_{h}^{2}} ,
\end{equation*}
i.e. with $\kappa =kh$

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\;
       \frac{\kappa\cosh\kappa}{\kappa^{2}+\cosh^{2}\kappa}\;,
\qquad 
\chi_{0}(\kappa)=\frac{\kappa\cosh\kappa}{\kappa^{2}+\cosh^{2}\kappa}
 =\Bigl[\frac{\kappa}{\cosh\kappa}+\frac{\cosh\kappa}{\kappa}\Bigr]^{-1} .
\end{equation*}
In particular
$\chi_{0}\approx\kappa$ for $\kappa\ll1$ and
$\chi_{0}\sim4\kappa e^{-\kappa}$ for $\kappa\gg1$.
If the normal stress at the surface is written with the
isostatic density contrast $\Delta\rho$,
$\sigma_{zz}=\Delta\rho\,g\,e\cos kx$, the same calculation gives
the conventional form

\[
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
       \chi(\kappa),\qquad 
\chi(\kappa)=\frac{\kappa\cosh\kappa}{\kappa^{2}+\cosh^{2}\kappa},
\qquad\kappa=k h,
\]

so that on the usual long-wave scale $\kappa\ll1$

\[
e_{s}\simeq \frac{k h}{\Delta\rho g}S_{0},
\]

up to the obvious $\rho\to\Delta\rho$ replacement.  With the
notation $e_{s}=\chi S_{0}/\Delta\rho g$ this is $\chi(\kappa)$ above,
$\chi\to\kappa$ for $kh\ll1$.  The sign is that of $S_{0}$; the
magnitude is the one quoted.  If the $\rho$ appearing in
$\sigma_{zz}= \rho g e\cos kx$ is kept distinct from the
isostatic contrast the familiar result is $e_{s}= (\rho/\Delta\rho)
\chi_{0}S_{0}/\rho g$, i.e. the same dimensionless shape factor
$\chi_{0}(\kappa)$ quoted above.

public_text.3:
In the linearised Stokes problem write with the stream function
$\psi(x,z)=\Psi(z)\sin kx$,

\begin{equation*}
u_{x}=\Psi'\sin kx ,\qquad u_{z}=-k\Psi\cos kx ,
\end{equation*}
so that $V(z)=-k\Psi(z)$ is the $z$–amplitude of $u_{z}$ and
$U(z)=\Psi'(z)=-V'/k $.  Putting $p=P(z)\cos kx$
\begin{equation*}
kP=\mu\Big[k^{2}\Psi'-\Psi'''\Big],\qquad 
P'=\mu k\Big[k^{2}\Psi-\Psi''\Big] ,
\end{equation*}
so that with $V=-k\Psi$
\begin{equation*}
V^{IV}-2k^{2}V''+k^{4}V=0,\qquad 
V(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}.
\end{equation*}
The stress components are
\begin{equation*}
\sigma_{xz}=\mu\big(\Psi''+k^{2}\Psi\big)\sin kx ,\qquad 
\sigma_{zz}=\Big[-P-2\mu k\Psi'\Big]\cos kx ,
\end{equation*}
and $P=2\mu\big[Be^{kz}+De^{-kz}\big]$.  Hence
\begin{equation*}
\sigma_{zz}=2\mu k\Big[(A+Bz)e^{kz}-(C+Dz)e^{-kz}\Big]\cos kx .
\end{equation*}
The kinematic conditions at the free surface are, to $O(e)$,
$u_{x}(0)=0$, $u_{z}(0)=\dot e$ and for a steady state
$u_{z}(0)=0$.  Thus

\begin{equation*}
V(0)=0,\qquad V'(0)=0 ,
\end{equation*}
i.e. $C=-A$ and $B+D+2kA=0$.  On the free surface
\begin{equation*}
\sigma_{zz}(0)=\rho g\,e\cos kx=-P(0)\cos kx ,
\end{equation*}
so that with $V'(0)=0$
\begin{equation*}
-P(0)=2\mu(B+D)=\rho g e,\qquad 
B+D=-\frac{\rho g e}{2\mu},
\end{equation*}
and $A=\rho g e/4\mu k$.  The lower free surface conditions are
\begin{equation*}
\sigma_{zz}(h)=0\;\;\Longleftrightarrow\;\;
\big(A+Bh\big)e^{kh}=\big(C+Dh\big)e^{-kh},
\end{equation*}
and
\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx\;\;\Longleftrightarrow\;\;
\mu\big(\Psi''+k^{2}\Psi\big)_{h}=S_{0},
\end{equation*}
i.e.
\begin{equation*}
-2\mu\Big[\big(B+kA+kBh\big)e^{kh}
+\big(kC-D+kDh\big)e^{-kh}\Big]=S_{0}.
\end{equation*}
With $C=-A$ and $B+D=-2kA$ the last two conditions give

\begin{equation*}
2\mu A\Big[\,\frac{S}{h}+\frac{4k^{2}h}{S}\Big]=S_{0},
\qquad S=e^{kh}+e^{-kh}=2\cosh kh ,
\end{equation*}
so that with $A=\rho g e/4\mu k$

\begin{equation*}
\frac{\rho g e}{2k}\Big[\frac{S}{h}+\frac{4k^{2}h}{S}\Big]=S_{0} .
\end{equation*}
Hence the steady, stress driven topography is

\begin{equation*}
e_{s}= \frac{2k\,S_{0}}{\rho g}
\frac{hS}{S^{2}+4k^{2}h^{2}}
     =\frac{k h\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}\,
       \frac{S_{0}}{\rho g}\;,
\end{equation*}
in particular
\begin{equation*}
e_{s}= \chi\,\frac{S_{0}}{\rho g},\qquad 
\chi(kh)=\frac{k h\,\cosh kh}{\cosh^{2}kh+k^{2}h^{2}}\;,
\end{equation*}
which is independent of the viscosity.  Putting the isostatic
restoring stress $\Delta\rho g e$ for the overlying air/water,
$\rho\to\Delta\rho$,

\[
e_{s}=\chi\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{k h\cosh kh}{\cosh^{2}kh+(k h)^{2}},
\]

so that for the long wave limit $kh\ll1$,

\[
\chi\simeq k h+O\!\left(k^{3}h^{3}\right),\qquad
e_{s}\simeq k h\,\frac{S_{0}}{\Delta\rho g}\;,
\]

the familiar thin–sheet limit.  With the conventional
isostatic density contrast $\Delta\rho$ the formal factor is the
same with $\rho$ replaced by $\Delta\rho$.  This is the
steady state reached after transients have decayed; the
amplitude is independent of the viscosity $\mu$ and is
normally quoted as $e_{s}\approx kh\,S_{0}/\Delta\rho g$ for
$kh\ll1$.  The $\rho$ in the statement can be identified with the
isostatic contrast $\Delta\rho$.

3.text:
For a Stokes flow write $\psi(x,z)=\Phi(z)\sin kx$, $u_{x}=\Phi'\sin kx $,
$w=-k\Phi\cos kx$.  With $s=kz$,
$\Phi''_{s}-2\Phi_{s}+ \Phi=0$ and with the locked top

\begin{equation*}
\Phi(0)=\Phi'(0)=0\qquad\Longleftrightarrow\qquad 
\Phi(s)=\gamma \big[\sinh s-s\cosh s\big]+\beta\,s\sinh s ,
\end{equation*}
up to an additive constant.  Then

\begin{equation*}
\sigma_{zz}= \frac{\mu}{k}\big[\Phi''' -3k^{2}\Phi'\big]\cos kx ,
\qquad 
\sigma_{xz}= \mu\big[\Phi''+k^{2}\Phi\big]\sin kx ,
\end{equation*}
and with $p=-\mu k^{-1}\big[\Phi'''-k^{2}\Phi'\big]\cos kx$.

On the free top $u_{x}(0)=0$, $w(0)=0$ and

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=\Delta\rho g\,e ,
\end{equation*}
so that with $\Phi'''(0)=-2k^{3}\gamma$

\begin{equation*}
\gamma=-\frac{\Delta \rho g}{2\mu k^{2}}\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is
$\Phi'''(h)=3k^{2}\Phi'(h)$ i.e.

\begin{equation*}
\gamma\big[-\cosh s+s\sinh s\big]=\beta\,s\cosh s ,
\qquad s=kh,
\end{equation*}
so that

\begin{equation*}
\beta =\gamma\,\frac{s\sinh s-\cosh s}{s\cosh s}\; .
\end{equation*}

The imposed basal shear is

\begin{equation*}
\mu\big[\Phi''(h)+k^{2}\Phi(h)\big]=S_{0}.
\end{equation*}
Now

\begin{equation*}
\Phi''(h)+k^{2}\Phi(h)=2k^{2}
\Big[-\gamma s\cosh s+\beta\big(\cosh s+s\sinh s\big)\Big] ,
\end{equation*}
and with the $\beta$ above

\begin{equation*}
\mu\big[\Phi''(h)+k^{2}\Phi(h)\big]
     =\rho g\,e\,\frac{s^{2}+\cosh^{2}s}{s\cosh s}\; .
\end{equation*}
Hence in the steady state $\dot e=0$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \frac{s\cosh s}{s^{2}+\cosh^{2}s},
\qquad s=kh,
\end{equation*}
i.e. in the notation $e_{s}=\chi S_{0}/\Delta\rho g$

\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
       =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1},
\qquad s=kh,
\end{equation*}
the usual viscous dynamic topography.  In particular
$\chi(s)=s+O(s^{3})$ for $s\ll1$ and $\chi(s)\sim2s\,e^{-s}$ for
$s\gg1$.  On the long wave scale $kh\ll1$,

\begin{equation*}
\chi\simeq kh=\frac{2\pi h}{\lambda},
\qquad 
e_{s}\simeq\frac{kh}{\Delta\rho g}\;S_{0},
\end{equation*}
which is the familiar $e_{s}\approx kh\,S_{0}/\Delta\rho g$ viscous
shear topography, $e_{s}= \chi S_{0}/\Delta\rho g$ with the
dimensionless shape factor $\chi(kh)$ above.  With the
conventional $\rho\equiv\Delta\rho$ replacement this is the
text-book $e_{s}= \chi S_{0}/\rho g$, $\chi=kh\cosh kh/
\big[(kh)^{2}+\cosh^{2}kh\big]$, $\chi\to kh$ for $kh\ll1$.
Up to the immaterial sign this is the stable viscous response
often quoted as $e_{s}\approx kh S_{0}/\Delta\rho g$ in the long wave
limit. ∎

