12.text:
With the 2--D Stokes flow put
$\psi(x,z)=F(z)\sin k x$ so that
$u_{x}=F^{\prime}\sin k x$, $u_{z}=-kF\cos k x$
and $\nabla^{4}\psi=0$,
\begin{equation*}
F^{IV}-2k^{2}F^{\prime\prime}+k^{4}F=0,
\qquad 
F(z)=(a+bz)\cosh kz+(c+dz)\sinh kz  .
\end{equation*}
On the locked impermeable lid $z=0$
\begin{equation*}
u_{x}(0)=0,\qquad w(0)=\dot e,
\end{equation*}
so that in the steady state $F(0)=F^{\prime}(0)=0$.
Up to an irrelevant additive constant
\begin{equation*}
F(z)=\gamma\bigl[\sinh s-s\cosh s\bigr]
      +\frac{\delta}{k}s\sinh s ,\qquad s=kz ,
\end{equation*}
and
\begin{equation*}
\sigma_{xz}=\mu\bigl[F^{\prime\prime}+k^{2}F\bigr]\sin kx,
\qquad 
\sigma_{zz}=\Bigl[-P-2\mu kF^{\prime}\Bigr]\cos kx,
\qquad 
P=-\frac{\mu}{k}\bigl[F^{\prime\prime\prime}-k^{2}F^{\prime}\bigr].
\end{equation*}
Hence with the free surface $\sigma_{zz}(0)=\Delta\rho g e\cos kx$
\begin{equation*}
\frac{\mu}{k}F^{\prime\prime\prime}(0)=\Delta\rho g e ,\qquad 
F^{\prime\prime\prime}(0)=-2k^{3}\gamma ,
\end{equation*}
i.e.
\begin{equation*}
\gamma=-\frac{\Delta\rho g e}{2\mu k^{2}} .
\end{equation*}
The stress free base is
\begin{equation*}
\sigma_{zz}(h)=0\iff F^{\prime\prime\prime}(h)=3k^{2}F^{\prime}(h),
\end{equation*}
which with the representation above gives
\begin{equation*}
\frac{\delta}{k}= \gamma\,
\frac{s\sinh s-\cosh s}{s\cosh s},\qquad s=kh,
\end{equation*}
and the imposed basal shear
\begin{equation*}
\mu\bigl[F^{\prime\prime}(h)+k^{2}F(h)\bigr]=S_{0}
\end{equation*}
becomes
\begin{equation*}
-2k^{2}\gamma\,
\frac{s^{2}+\cosh^{2}s}{s\cosh s}= \frac{S_{0}}{\mu}\; .
\end{equation*}
Eliminating $\gamma$ with $\gamma=-\Delta\rho g e_{s}/2\mu k^{2}$ the
viscosity drops out and
\begin{equation*}
\frac{\Delta\rho g e_{s}}{k}\,
\frac{s^{2}+\cosh^{2}s}{s\cosh s}=S_{0},
\end{equation*}
i.e. with $s=kh$
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{s\cosh s}{s^{2}+\cosh^{2}s},
\qquad s=k h=\frac{2\pi h}{\lambda}\; .
\end{equation*}
In the notation $e_{s}=\chi S_{0}/\Delta\rho g$
\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
       =\Bigl[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Bigr]^{-1}
       =\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
the usual viscous channel dynamic topography.  Up to the sign
convention $e_{s}\propto -S_{0}$ the magnitude is the one above.
In particular
\begin{equation*}
\chi(s)=s\bigl[1+O(s^{2})\bigr],\qquad s\ll1,
\end{equation*}
so that on the long wave scale
\begin{equation*}
e_{s}\simeq \frac{kh}{\Delta\rho g}S_{0}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
and $\chi(s)\sim2s\,e^{-s}$ for $s\gg1$.  With the conventional
$\rho\to\Delta\rho$ replacement this is the steady Stokes response
to a harmonic basal traction $S_{0}\sin kx$.  The sign is that of
the chosen phase, $e_{s}=-\chi S_{0}/\Delta\rho g$ for the $\sin kx$
traction giving a $\cos kx$ topography, the magnitude being the
$\chi$ quoted above.  This is the $kh\cosh kh/[(kh)^{2}+\cosh^{2}kh]$
shape factor obtained by colleagues 10,11,12,2,3,6,8 and is the
standard viscous dynamic topography limit. ∎

4.text:
With the stream function $\psi (x,z)=f(z)\sin kx$
\begin{equation*}
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx ,
\qquad 
\nabla^{4}\psi =0,
\end{equation*}
\begin{equation*}
f^{IV}-2k^{2}f''+k^{4}f=0 ,
\qquad 
f(z)=\bigl(A+Bz\bigr)\cosh kz+\bigl(C+Dz\bigr)\sinh kz .
\end{equation*}
The free material top $z=0$ is $u_{x}=0$, $w(0)=\dot e$.  In the
steady state $w(0)=0$,
\begin{equation*}
f(0)=0,\qquad f'(0)=0,
\end{equation*}
i.e.  up to a rigid body mode
\begin{equation*}
f(z)=C\Big[\sinh kz-kz\cosh kz\Big]+Dz\sinh kz,
\qquad 
f'(0)=0,\qquad f(0)=0 .
\end{equation*}
Put
\begin{equation*}
P(z)=-\frac{\mu}{k}\Big[f'''-k^{2}f'\Big] ,\qquad 
p=P\cos kx ,
\end{equation*}
then
\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \frac{\mu}{k}\Big[f'''-3k^{2}f'\Big]\cos kx .
\end{equation*}
Hence at the free top $f'(0)=0$
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
       =\rho g\,e\cos kx, \qquad 
f'''(0)=-2k^{3}C,
\end{equation*}
so that with the isostatic contrast $\Delta\rho$
\begin{equation*}
C=-\frac{\Delta\rho g e}{2\mu k^{2}},\qquad
f'''(0)=\frac{k\Delta\rho g}{\mu}e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is
\begin{equation*}
f'''(h)-3k^{2}f'(h)=0,
\end{equation*}
i.e.
\begin{equation*}
- C\cosh kh+Ckh\sinh kh-Dh\cosh kh =0,
\end{equation*}
\begin{equation*}
D=C\,\frac{kh\sinh kh-\cosh kh}{h\cosh kh}\; .
\end{equation*}
The imposed basal shear is
\begin{equation*}
\mu\big[f''+k^{2}f\big]_{h}=S_{0},
\end{equation*}
and with the above $f$
\begin{equation*}
f''+k^{2}f
 =2k\Big[D\cosh kz+Dkz\sinh kz-Ck^{2}z\cosh kz\Big],
\end{equation*}
so that on the base
\begin{equation*}
f''+k^{2}f\Big|_{h}
 =-\frac{2kC}{h\cosh kh}\Big[(kh)^{2}+\cosh^{2}kh\Big].
\end{equation*}
Hence
\begin{equation*}
-\frac{2\mu kC}{h\cosh kh}\Big[(kh)^{2}+\cosh^{2}kh\Big]=S_{0} .
\end{equation*}
Eliminating $C$ with $C=-\Delta\rho g e/2\mu k^{2}$,
\begin{equation*}
\frac{\Delta\rho g e}{k}
\frac{(kh)^{2}+\cosh^{2}kh}{h\cosh kh}=S_{0},
\end{equation*}
i.e. with $s=kh=2\pi h/\lambda$
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{s\cosh s}{s^{2}+\cosh^{2}s}
      =\frac{S_{0}}{\Delta\rho g}\,
\chi(s),\qquad 
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
       =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1},
\end{equation*}
the steady viscous dynamic topography driven by the harmonic basal
traction $S_{0}\sin kx$.  In particular
\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,
\qquad 
\chi(s)\sim2s\,e^{-s},\qquad s\gg1 ,
\end{equation*}
so that on the usual long wave, thin plate scale $kh\ll1$
\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},\qquad
\chi_{0}\simeq kh,
\end{equation*}
the familiar $e_{s}\propto hS_{0}/\lambda\Delta\rho g$ viscous channel
law.  With the notation $\sigma_{zz}=\rho ge\cos kx$ the same
functional form is $e_{s}= \chi S_{0}/\rho g$ with the $\chi(s)$ above;
the replacement $\rho\to\Delta\rho$ is the customary geophysical
isostatic contrast.  The sinh–numerator form,
$\chi_{s}=s\sinh s/(s^{2}+\cosh^{2}s)$, is obtained with the
impermeable-bottom gauge $f(h)=0$ instead of the stated
$\sigma_{zz}(h)=0$, and reduces to the same $kh$ long wave limit. ∎

3.text:
With the harmonic mode $\psi(x,z,t)=\Phi(z)\sin kx$

\begin{equation*}
u_{x}=\Phi'\sin kx ,\qquad w=-k\Phi\cos kx ,
\qquad \nabla^{4}\Phi=0 ,
\end{equation*}
the locked, steady free surface is
$\Phi(0)=0,\;\Phi'(0)=0$ and with $s=kz$

\begin{equation*}
\Phi(s)=C\Big[\sinh s-s\cosh s\Big]+ \frac{D}{k}\,s\sinh s ,
\qquad \Phi'(0)=0 ,
\end{equation*}
so that

\begin{equation*}
\sigma_{zz}=\frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx ,\qquad
\sigma_{xz}= \mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx ,
\end{equation*}
and with $p=-\mu k^{-1}\big[\Phi'''-k^{2}\Phi'\big]\cos kx$.
On the free surface $w(0)=0$ and $u_{x}(0)=0$,
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=\Delta\rho g\,e ,
\qquad 
\Phi'''(0)=-2k^{3}C,
\end{equation*}
i.e.
\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $\Phi'''(h)=3k^{2}\Phi'(h)$
which gives
\begin{equation*}
\frac{D}{k}=C\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}},\qquad 
s_{h}=kh ,
\end{equation*}
and the imposed basal shear
\begin{equation*}
\mu\big[\Phi''(h)+k^{2}\Phi(h)\big]=S_{0}
\end{equation*}
gives with the above $C,D$

\begin{equation*}
\mu\big[\Phi''(h)+k^{2}\Phi(h)\big]
     =-2\mu k^{2}C\Big[\frac{\cosh s_{h}}{s_{h}}
                       +\frac{s_{h}}{\cosh s_{h}}\Big]=S_{0}\; .
\end{equation*}
Hence with $C=-\Delta\rho g e/2\mu k^{2}$

\begin{equation*}
\Delta\rho g\,e_{s}
\Big[\frac{\cosh s_{h}}{s_{h}}+\frac{s_{h}}{\cosh s_{h}}\Big]=S_{0},
\end{equation*}
i.e. in the steady state $\dot e=0$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{s_{h}\cosh s_{h}}{s_{h}^{2}+\cosh^{2}s_{h}},\qquad 
s_{h}=kh=\frac{2\pi h}{\lambda},
\end{equation*}
so that with the notation $e_{s}=\chi S_{0}/\Delta\rho g$

\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
      =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1},
\qquad s=kh,
\end{equation*}
is the viscous dynamic topography factor. In particular

\begin{equation*}
\chi(s)=s+O(s^{3}),\qquad s\ll1,\qquad 
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
and on the usual long wave $kh\ll1$ scale

\begin{equation*}
\chi\simeq kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq\frac{kh}{\Delta\rho g}\,S_{0}
       =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar $e_{s}\approx kh\,S_{0}/\Delta\rho g$ viscous shear
topography.  Up to the conventional $\rho\leftrightarrow\Delta\rho$
identification this is the text–book $e_{s}= \chi S_{0}/\rho g$ with
$\chi(kh)=kh\cosh kh\big[(kh)^{2}+\cosh^{2}kh\big]^{-1}$, i.e. the
quoted $\chi\to kh$ long-wave limit.  The sign is that of $S_{0}$,
a positive basal traction $\sin kx$ producing a $\cos kx$ high at the
free surface. ∎

11.text:
With the stream function $\psi =f(z)\sin kx$, $u_{x}=f'\sin kx$,
$u_{z}=-k f\cos kx$, $\nabla^{4}\psi =0$,
$$
f''''-2k^{2}f''+k^{4}f=0\,,\qquad 
f(z)=(A+Bz)\cosh kz+(C+Dz)\sinh kz .
$$
$u_{x}(0)=0,\;w(0)=\dot e$ gives for the steady state
$f(0)=f'(0)=0$ i.e. $A=0,\;C=-B/k$ and with $\xi =kz$

\begin{equation*}
f(z)=\alpha\Big[\,\xi\cosh\xi-\sinh\xi\Big]
      +\beta\,\xi\sinh\xi,\qquad 
\alpha=\frac{B}{k},\;\;\beta=\frac{D}{k}\;,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\bigl[f''+k^{2}f\bigr]\sin kx,\qquad
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx  .
\end{equation*}
On the locked top $f'(0)=0$,
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
       =\Delta\rho g\,e\cos kx,\qquad
f'''(0)=2k^{3}\alpha ,
\end{equation*}
so that
\begin{equation*}
\alpha=\frac{\Delta\rho g}{2\mu k^{2}}\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
i.e. with $\xi_{h}=kh$
\begin{equation*}
\alpha\bigl[\,c_{h}-\xi_{h}s_{h}\bigr]=\beta\xi_{h}c_{h},
\qquad c_{h}=\cosh\xi_{h},~s_{h}=\sinh\xi_{h},
\end{equation*}
and the imposed basal shear
\begin{equation*}
\mu\bigl[f''(h)+k^{2}f(h)\bigr]=S_{0}
\end{equation*}
gives with $f''+k^{2}f =2k^{2}\bigl[\alpha\xi c+\beta(c+\xi s)\bigr]$
\begin{equation*}
2\mu k^{2}\Big[\alpha\xi_{h}c_{h}
     +\beta\bigl(c_{h}+\xi_{h}s_{h}\bigr)\Big]=S_{0} .
\end{equation*}
Eliminating $\beta$ with $\beta=\alpha\,(c_{h}-\xi_{h}s_{h})
/\xi_{h}c_{h}$,
\begin{equation*}
2\mu\alpha\Big[\frac{\xi_{h}}{c_{h}}+\frac{c_{h}}{\xi_{h}}\Big]=S_{0},
\end{equation*}
and with $\alpha=\Delta\rho g e_{s}/2\mu k^{2}$,
\begin{equation*}
\Delta\rho g e_{s}\Big[\frac{\xi_{h}}{c_{h}}
      +\frac{c_{h}}{\xi_{h}}\Big]=S_{0} .
\end{equation*}
Hence with $e_{s}=\chi S_{0}/\Delta\rho g$ and $\xi_{h}=kh$
\begin{equation*}
\chi(\xi)=\frac{1}{\displaystyle\frac{\xi}{\cosh\xi}
          +\frac{\cosh\xi}{\xi}}
       =\frac{\xi\cosh\xi}{\xi^{2}+\cosh^{2}\xi}\;,
\qquad\xi=kh=\frac{2\pi h}{\lambda}\;,
\end{equation*}
i.e.
\[
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
      \frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\]
the viscosity dropping out of the steady amplitude.  In particular
\[
\chi(\xi)=\xi\Big[\,1-\tfrac32\xi^{2}+O(\xi^{4})\Big],
\qquad \xi\ll1,
\]
so that on the usual long wave scale
\[
e_{s}\simeq\frac{kh}{\Delta\rho g}\,S_{0}
        =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\]
and $\chi\sim2\xi e^{-\xi}$ for $kh\gg1$.  With the conventional
$\rho\to\Delta\rho$ identification this is the familiar
$e_{s}\approx kh\,S_{0}/\Delta\rho g$ viscous dynamic topography, the
exact Stokes factor being $\chi(kh)=kh\cosh kh/[(kh)^{2}+\cosh^{2}kh]$.
Up to the $\rho/\Delta\rho$ notation this is the quoted
$\,e_{s}= \chi S_{0}/\Delta\rho g$ with $\chi\to kh$ for $kh\ll1$, as
often written $e_{s}\simeq kh\,S_{0}/\Delta\rho g$. ∎

public_text.12:
With the 2--D Stokes flow put
$\psi(x,z)=F(z)\sin k x$ so that
$u_{x}=F^{\prime}\sin k x$, $u_{z}=-kF\cos k x$
and $\nabla^{4}\psi=0$,
\begin{equation*}
F^{IV}-2k^{2}F^{\prime\prime}+k^{4}F=0,
\qquad 
F(z)=(a+bz)\cosh kz+(c+dz)\sinh kz  .
\end{equation*}
On the locked impermeable lid $z=0$
\begin{equation*}
u_{x}(0)=0,\qquad w(0)=\dot e,
\end{equation*}
so that in the steady state $F(0)=F^{\prime}(0)=0$.
Up to an irrelevant additive constant
\begin{equation*}
F(z)=\gamma\bigl[\sinh s-s\cosh s\bigr]
      +\frac{\delta}{k}s\sinh s ,\qquad s=kz ,
\end{equation*}
and
\begin{equation*}
\sigma_{xz}=\mu\bigl[F^{\prime\prime}+k^{2}F\bigr]\sin kx,
\qquad 
\sigma_{zz}=\Bigl[-P-2\mu kF^{\prime}\Bigr]\cos kx,
\qquad 
P=-\frac{\mu}{k}\bigl[F^{\prime\prime\prime}-k^{2}F^{\prime}\bigr].
\end{equation*}
Hence with the free surface $\sigma_{zz}(0)=\Delta\rho g e\cos kx$
\begin{equation*}
\frac{\mu}{k}F^{\prime\prime\prime}(0)=\Delta\rho g e ,\qquad 
F^{\prime\prime\prime}(0)=-2k^{3}\gamma ,
\end{equation*}
i.e.
\begin{equation*}
\gamma=-\frac{\Delta\rho g e}{2\mu k^{2}} .
\end{equation*}
The stress free base is
\begin{equation*}
\sigma_{zz}(h)=0\iff F^{\prime\prime\prime}(h)=3k^{2}F^{\prime}(h),
\end{equation*}
which with the representation above gives
\begin{equation*}
\frac{\delta}{k}= \gamma\,
\frac{s\sinh s-\cosh s}{s\cosh s},\qquad s=kh,
\end{equation*}
and the imposed basal shear
\begin{equation*}
\mu\bigl[F^{\prime\prime}(h)+k^{2}F(h)\bigr]=S_{0}
\end{equation*}
becomes
\begin{equation*}
-2k^{2}\gamma\,
\frac{s^{2}+\cosh^{2}s}{s\cosh s}= \frac{S_{0}}{\mu}\; .
\end{equation*}
Eliminating $\gamma$ with $\gamma=-\Delta\rho g e_{s}/2\mu k^{2}$ the
viscosity drops out and
\begin{equation*}
\frac{\Delta\rho g e_{s}}{k}\,
\frac{s^{2}+\cosh^{2}s}{s\cosh s}=S_{0},
\end{equation*}
i.e. with $s=kh$
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{s\cosh s}{s^{2}+\cosh^{2}s},
\qquad s=k h=\frac{2\pi h}{\lambda}\; .
\end{equation*}
In the notation $e_{s}=\chi S_{0}/\Delta\rho g$
\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
       =\Bigl[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Bigr]^{-1}
       =\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\end{equation*}
the usual viscous channel dynamic topography.  Up to the sign
convention $e_{s}\propto -S_{0}$ the magnitude is the one above.
In particular
\begin{equation*}
\chi(s)=s\bigl[1+O(s^{2})\bigr],\qquad s\ll1,
\end{equation*}
so that on the long wave scale
\begin{equation*}
e_{s}\simeq \frac{kh}{\Delta\rho g}S_{0}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
and $\chi(s)\sim2s\,e^{-s}$ for $s\gg1$.  With the conventional
$\rho\to\Delta\rho$ replacement this is the steady Stokes response
to a harmonic basal traction $S_{0}\sin kx$.  The sign is that of
the chosen phase, $e_{s}=-\chi S_{0}/\Delta\rho g$ for the $\sin kx$
traction giving a $\cos kx$ topography, the magnitude being the
$\chi$ quoted above.  This is the $kh\cosh kh/[(kh)^{2}+\cosh^{2}kh]$
shape factor obtained by colleagues 10,11,12,2,3,6,8 and is the
standard viscous dynamic topography limit. ∎

