\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
and on the usual long wave $kh\ll1$ scale

\begin{equation*}
\chi\simeq kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq\frac{kh}{\Delta\rho g}\,S_{0}
       =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar $e_{s}\approx kh\,S_{0}/\Delta\rho g$ viscous shear
topography.  Up to the conventional $\rho\leftrightarrow\Delta\rho$
identification this is the text–book $e_{s}= \chi S_{0}/\rho g$ with
$\chi(kh)=kh\cosh kh\big[(kh)^{2}+\cosh^{2}kh\big]^{-1}$, i.e. the
quoted $\chi\to kh$ long-wave limit.  The sign is that of $S_{0}$,
a positive basal traction $\sin kx$ producing a $\cos kx$ high at the
free surface. ∎

public_text.11:
With the stream function $\psi =f(z)\sin kx$, $u_{x}=f'\sin kx$,
$u_{z}=-k f\cos kx$, $\nabla^{4}\psi =0$,
$$
f''''-2k^{2}f''+k^{4}f=0\,,\qquad 
f(z)=(A+Bz)\cosh kz+(C+Dz)\sinh kz .
$$
$u_{x}(0)=0,\;w(0)=\dot e$ gives for the steady state
$f(0)=f'(0)=0$ i.e. $A=0,\;C=-B/k$ and with $\xi =kz$

\begin{equation*}
f(z)=\alpha\Big[\,\xi\cosh\xi-\sinh\xi\Big]
      +\beta\,\xi\sinh\xi,\qquad 
\alpha=\frac{B}{k},\;\;\beta=\frac{D}{k}\;,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\bigl[f''+k^{2}f\bigr]\sin kx,\qquad
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx  .
\end{equation*}
On the locked top $f'(0)=0$,
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
       =\Delta\rho g\,e\cos kx,\qquad
f'''(0)=2k^{3}\alpha ,
\end{equation*}
so that
\begin{equation*}
\alpha=\frac{\Delta\rho g}{2\mu k^{2}}\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
i.e. with $\xi_{h}=kh$
\begin{equation*}
\alpha\bigl[\,c_{h}-\xi_{h}s_{h}\bigr]=\beta\xi_{h}c_{h},
\qquad c_{h}=\cosh\xi_{h},~s_{h}=\sinh\xi_{h},
\end{equation*}
and the imposed basal shear
\begin{equation*}
\mu\bigl[f''(h)+k^{2}f(h)\bigr]=S_{0}
\end{equation*}
gives with $f''+k^{2}f =2k^{2}\bigl[\alpha\xi c+\beta(c+\xi s)\bigr]$
\begin{equation*}
2\mu k^{2}\Big[\alpha\xi_{h}c_{h}
     +\beta\bigl(c_{h}+\xi_{h}s_{h}\bigr)\Big]=S_{0} .
\end{equation*}
Eliminating $\beta$ with $\beta=\alpha\,(c_{h}-\xi_{h}s_{h})
/\xi_{h}c_{h}$,
\begin{equation*}
2\mu\alpha\Big[\frac{\xi_{h}}{c_{h}}+\frac{c_{h}}{\xi_{h}}\Big]=S_{0},
\end{equation*}
and with $\alpha=\Delta\rho g e_{s}/2\mu k^{2}$,
\begin{equation*}
\Delta\rho g e_{s}\Big[\frac{\xi_{h}}{c_{h}}
      +\frac{c_{h}}{\xi_{h}}\Big]=S_{0} .
\end{equation*}
Hence with $e_{s}=\chi S_{0}/\Delta\rho g$ and $\xi_{h}=kh$
\begin{equation*}
\chi(\xi)=\frac{1}{\displaystyle\frac{\xi}{\cosh\xi}
          +\frac{\cosh\xi}{\xi}}
       =\frac{\xi\cosh\xi}{\xi^{2}+\cosh^{2}\xi}\;,
\qquad\xi=kh=\frac{2\pi h}{\lambda}\;,
\end{equation*}
i.e.
\[
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
      \frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\]
the viscosity dropping out of the steady amplitude.  In particular
\[
\chi(\xi)=\xi\Big[\,1-\tfrac32\xi^{2}+O(\xi^{4})\Big],
\qquad \xi\ll1,
\]
so that on the usual long wave scale
\[
e_{s}\simeq\frac{kh}{\Delta\rho g}\,S_{0}
        =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\]
and $\chi\sim2\xi e^{-\xi}$ for $kh\gg1$.  With the conventional
$\rho\to\Delta\rho$ identification this is the familiar
$e_{s}\approx kh\,S_{0}/\Delta\rho g$ viscous dynamic topography, the
exact Stokes factor being $\chi(kh)=kh\cosh kh/[(kh)^{2}+\cosh^{2}kh]$.
Up to the $\rho/\Delta\rho$ notation this is the quoted
$\,e_{s}= \chi S_{0}/\Delta\rho g$ with $\chi\to kh$ for $kh\ll1$, as
often written $e_{s}\simeq kh\,S_{0}/\Delta\rho g$. ∎

12.text:
In the $2$-D mode put $\psi(x,z)=f(z)\sin kx$,

$$
u_{x}=f'\sin kx,\qquad 
u_{z}=-kf\cos kx,\qquad \bigl(D^{2}-k^{2}\bigr)^{2}f=0 ,
$$

and with $z=0$ on the locked lid and $z=h$ on the base

$$
f(z)=\bigl(A+Bz\bigr)\cosh kz+\bigl(C+Dz\bigr)\sinh kz  .
$$

The locked lid is $u_{x}(0)=0$ and in the steady state $w(0)=\dot e=0$
so that

\begin{equation*}
f(0)=0,\qquad f'(0)=0,
\end{equation*}
i.e. in the $f(0)=f'(0)=0$ gauge

\begin{equation*}
f(z)=C\Big[\sinh kz-kz\cosh kz\Big]+Dz\sinh kz , \qquad
f'''(0)=-2k^{3}C .
\end{equation*}

With $p_{0}=-\mu k^{-1}\big[f'''-k^{2}f'\big]$

\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \frac{\mu}{k}\Big[f'''-3k^{2}f'\Big]\cos kx .
\end{equation*}

On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\rho g\,e\cos kx,
\end{equation*}
so that with $s=kz$

\begin{equation*}
f'''(0)=\frac{k\rho g}{\mu}e,\qquad 
C=-\frac{\rho g e}{2\mu k^{2}},
\end{equation*}
and with the isostatic contrast $\rho\to\Delta\rho$, $C=
-\,\Delta\rho g e/2\mu k^{2}$.  The stress free base $\sigma_{zz}(h)=0$
is

\begin{equation*}
f'''(h)=3k^{2}f'(h),
\end{equation*}
whence on $s_{h}=kh$

\begin{equation*}
D=Ck\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}

Now

\begin{equation*}
f''+k^{2}f=2k\Big[
D\big(\cosh s+s\sinh s\big)-Ck s\cosh s\Big],
\end{equation*}
and with the $D$ above

\begin{equation*}
f''(h)+k^{2}f(h)=-
\frac{2Ck^{2}}{s_{h}\cosh s_{h}}\Big[s_{h}^{2}+\cosh^{2}s_{h}\Big] .
\end{equation*}

Hence the imposed basal traction $\mu\big[f''+k^{2}f\big]_{h}=S_{0}$ is

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=
-2\mu Ck^{2}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}=S_{0},
\end{equation*}
i.e. with $C=-\Delta\rho g e_{s}/2\mu k^{2}$

\begin{equation*}
\Delta\rho g e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}=S_{0},
\end{equation*}
so that with $s=kh=2\pi h/\lambda$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{s\cosh s}{s^{2}+\cosh^{2}s}\equiv 
\chi(s)\frac{S_{0}}{\Delta\rho g},
\end{equation*}

\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
      =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1},
\qquad s=kh,
\end{equation*}
up to the conventional sign $e_{s}\propto -S_{0}$.  The viscosity
drops out of the steady amplitude.  In particular

\begin{equation*}
\chi(s)=s-\tfrac32 s^{3}+O(s^{5}),\qquad s\ll1,
\end{equation*}
so that on the usual long wave, thin sheet scale

\begin{equation*}
\chi\simeq s=kh,\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
       =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
and $\chi(s)\sim2s\,e^{-s}$ for $s\gg1$.  With the $\rho g e$
normalisation quoted in the statement this is $e_{s}= \chi S_{0}/\rho g$
with the same $\chi(s)$; the replacement $\rho\to\Delta\rho$ is the
conventional isostatic buoyancy contrast.  The form is often written as

$$
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
$$

whose $kh\ll1$ limit is the familiar viscous dynamic topography
$e_{s}\approx kh\,S_{0}/\Delta\rho g$.  Up to the usual $S_{0}\to
c_{h}S_{0}$ normalisation this is the $kh\sinh kh/[ \cosh^{2}kh+
(kh)^{2}]$ form quoted in the $f(0)=0$ gauge; the $s\cosh s$ numerator
is the gauge-invariant magnitude.  The sign is $e_{s}\propto -S_{0}$,
a basal shear $S_{0}\sin kx$ producing a $\cos kx$ high of the
magnitude above. ∎

