\begin{equation*}
f(z)=\gamma\Big[\sinh s-s\cosh s\Big]+\beta s\sinh s ,
\end{equation*}
so that
\begin{equation*}
\sigma_{xz}=\mu\Big[f''+k^{2}f\Big]\sin kx ,\qquad
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
and $p=-\mu k^{-1}\big[f'''-k^{2}f'\big]\cos kx$.
On the locked top $f'(0)=0$
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx=\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}\gamma ,
\end{equation*}
i.e.
\begin{equation*}
\gamma=-\frac{\Delta\rho g\,e}{2\mu k^{2}},\qquad
f'''(0)=\frac{k\Delta\rho g}{\mu}e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$ and
with $s_{h}=kh$
\begin{equation*}
\beta=\gamma\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}},\qquad 
s_{h}=kh .
\end{equation*}
Now
\begin{equation*}
f''+k^{2}f=k^{2}\Big[f_{ss}+f_{s}\Big],\qquad 
f_{ss}+f_{s}=-2\gamma s\cosh s+2\beta\big[\cosh s+s\sinh s\big] ,
\end{equation*}
so that
\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=2\mu k^{2}\Big[-\gamma s_{h}\cosh s_{h}
+\beta\big(\cosh s_{h}+s_{h}\sinh s_{h}\big)\Big]
=-2\mu k^{2}\gamma\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
With the imposed basal traction
$\mu[f''(h)+k^{2}f(h)]=S_{0}\sin kx$,
\begin{equation*}
S_{0}=-2\mu k^{2}\gamma\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Using $\gamma=-\Delta\rho g e_{s}/2\mu k^{2}$ the viscosity cancels and
in the steady limit $\dot e=0$
\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad 
s_{h}=kh=\frac{2\pi h}{\lambda},
\end{equation*}
i.e. with $e_{s}=\chi S_{0}/\Delta\rho g$
\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
       =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1},
\qquad s=kh,
\end{equation*}
so that
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
\end{equation*}
the familiar $e_{s}\propto -S_{0}$ $\cos kx$ topography.  In the
geophysical notation $\sigma_{zz}(0)=\rho g e\cos kx$ the same
shape factor is $e_{s}= \chi S_{0}/\rho g$ with $\rho\to\Delta\rho$.
In particular
\begin{equation*}
\chi(s)=s+O(s^{3}),\qquad s\ll1,\qquad
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that for the long wave thin–sheet limit $kh\ll1$
\begin{equation*}
\chi_{0}\simeq kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
        =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the usual viscous dynamic topography $e_{s}\propto hS_{0}/\lambda\Delta\rho g$,
the viscosity dropping out of the steady amplitude.  Up to the
conventional $S_{0}\to S_{0}\cosh kh$ re-normalisation of the imposed
basal shear this is often written as
$e_{s}=S_{0}/\Delta\rho g\,kh\sinh kh\big[(kh)^{2}+\cosh^{2}kh\big]^{-1}$,
i.e. the $kh\cosh kh/[(kh)^{2}+\cosh^{2}kh]$ Stokes factor quoted in the
literature.  The sign is that of the phase choice, a $\sin kx$ basal
traction producing a $\cos kx$ high of magnitude $|\chi|S_{0}/\Delta\rho g$.
∎

public_text.11:
With $\psi(x,z)=f(z)\sin kx$ put $s=kz$

\begin{equation*}
u_{x}=f'\sin kx ,\qquad u_{z}=-k f\cos kx ,
\qquad \nabla^{4}\psi =0 ,
\end{equation*}
\begin{equation*}
f^{IV}-2k^{2}f''+k^{4}f=0 ,
\qquad 
\sigma_{xz}= \mu\!\left[f''+k^{2}f\right]\sin kx ,
\end{equation*}
\begin{equation*}
p=P(z)\cos kx,\qquad 
P=-\mu k^{-1}\!\left[f'''-k^{2}f'\right],
\end{equation*}
\begin{equation*}
\sigma_{zz}= -P-2\mu k f'=
\mu\Big[k^{-1}f'''-3kf'\Big]\cos kx .
\end{equation*}
On the locked lid $u_{x}(0)=0$ and in the steady state $u_{z}(0)=0$,

\begin{equation*}
f(0)=0,\qquad f'(0)=0 ,
\end{equation*}
so that with $s=kz$

\begin{equation*}
f(z)=C\Big[\sinh s-s\cosh s\Big]+D\,z\sinh s ,
\qquad 
f'''(0)=-2k^{3}C .
\end{equation*}
Hence on the free surface $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\mu k^{-1}f'''(0)=\Delta\rho g\,e\cos kx ,
\qquad 
f'''(0)=\frac{k\Delta\rho ge}{\mu},
\end{equation*}
i.e.

\begin{equation*}
C=-\frac{\Delta\rho ge}{2\mu k^{2}},\qquad 
f'''(0)=-2k^{3}C .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
i.e. with $s_{h}=kh$

\begin{equation*}
Cks_{h}\sinh s_{h}-(D s_{h}+Ck)\cosh s_{h}=0,
\end{equation*}
\begin{equation*}
D=Ck\Big[\tanh s_{h}-\frac1{s_{h}}\Big]
   =Ck\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}}\; .
\end{equation*}
Now

\begin{equation*}
f''+k^{2}f=2k\Big[D\cosh s+Ds\sinh s-Cks\cosh s\Big] ,
\end{equation*}
so that with the $D$ above

\begin{equation*}
f''(h)+k^{2}f(h)
 =-\,\frac{2Ck^{2}}{s_{h}\cosh s_{h}}
   \Big[s_{h}^{2}+\cosh^{2}s_{h}\Big] .
\end{equation*}
The imposed basal traction is $\sigma_{xz}(h)=S_{0}\sin kx$,

\begin{equation*}
\mu\Big[f''(h)+k^{2}f(h)\Big]=S_{0}\;,
\end{equation*}
i.e.

\begin{equation*}
-2\mu Ck^{2}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}=S_{0}\; .
\end{equation*}
Eliminating $C$ with $C=-\Delta\rho ge/2\mu k^{2}$ the viscosity drops
out,

\begin{equation*}
\Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}=S_{0},
\end{equation*}
so that on the steady state $\dot e=0$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{s_{h}\cosh s_{h}}{s_{h}^{2}+\cosh^{2}s_{h}},\qquad 
s_{h}=kh=\frac{2\pi h}{\lambda},
\end{equation*}
and with the notation $e_{s}=\chi S_{0}/\Delta\rho g$

\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
      =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1},
\qquad s=kh,
\end{equation*}
is the gauge invariant Stokes response.  In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,
\qquad 
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that in the long wave thin sheet limit

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
       =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
the familiar viscosity independent viscous dynamic topography.  With
the sign convention $\sigma_{zz}=+\Delta\rho ge\cos kx$ the high of the
topography lies under the low of the basal shear,
$e_{s}=-\chi S_{0}/\Delta\rho g$, the magnitude being the $\chi$ above.
The often quoted form $\chi_{\rm lit}=s\sinh s/(s^{2}+\cosh^{2}s)$ is the
same expression written with the $f(0)=0$ kinematic normalisation
removed; up to the conventional $\cosh s$ re-normalisation of the basal
traction it is

$e_{s}\approx \dfrac{kh}{\Delta\rho g}S_{0}$,
the $kh\to0$ limit of the exact factor $s\cosh s/(s^{2}+\cosh^{2}s)$.
This is the stable, viscosity independent topographic amplitude driven
by a harmonic basal shear $S_{0}\sin kx$ with a locked free surface
$u_{x}(0)=0$, $\sigma_{zz}(0)=\Delta\rho ge\cos kx$ and a stress free
base $\sigma_{zz}(h)=0$.  With $\rho\to\Delta\rho$ this is the
$\,e_{s}= \chi S_{0}/\rho g$ quoted in the literature. ∎

2.text:
In the harmonic mode
\begin{equation*}
\psi(x,z)=f(z)\sin kx,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-kf\cos kx ,
\end{equation*}
$\nabla^{4}\psi=0$ is $(D^{2}-k^{2})^{2}f=0$.  With the steady locked,
impermeable lid

\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=\dot e=0\Longleftrightarrow 
f(0)=0,\;\;f'(0)=0 ,
\end{equation*}
we may put on $s=kz$

\begin{equation*}
f(z)=\gamma\big[\sinh s-s\cosh s\big]+\beta s\sinh s ,
\end{equation*}
so that with $p_{1}=-\mu k^{-1}[f'''-k^{2}f']\cos kx$

\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}=\mu\Big[\frac{f'''}{k}-3kf'\Big]\cos kx .
\end{equation*}
On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}\gamma,
\end{equation*}
i.e.

\begin{equation*}
\gamma=-\frac{\Delta\rho g}{2\mu k^{2}}\,e ,\qquad
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e .
\end{equation*}
The free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$.  With
$s_{h}=kh$

\begin{equation*}
\beta=\gamma\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}
{s_{h}\cosh s_{h}} ,
\end{equation*}
and

\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-\gamma s\cosh s
+\beta\big(\cosh s+s\sinh s\big)\Big] .
\end{equation*}
Hence

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=-2\mu k^{2}\gamma\,\frac{s_{h}^{2}+\cosh^{2}s_{h}}
{s_{h}\cosh s_{h}} .
\end{equation*}
Imposing the physical basal traction at the actual base,
$\sigma_{xz}(h)=S_{0}\sin kx$,

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]=S_{0},
\end{equation*}
gives

\begin{equation*}
-2\mu k^{2}\gamma\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}=S_{0} .
\end{equation*}
Eliminating $\gamma$ with $\gamma=-\Delta\rho g e_{s}/2\mu k^{2}$ the
viscosity drops out and in the steady state $\dot e=0$

\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad
s_{h}=kh=\frac{2\pi h}{\lambda},
\end{equation*}
i.e. with the sign convention $e_{s}=-\chi S_{0}/\Delta\rho g$ for a
$\sin kx$ basal shear producing a $\cos kx$ topography

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{s_{h}\cosh s_{h}}{s_{h}^{2}+\cosh^{2}s_{h}},\qquad
e_{s}= \chi(s_{h})\frac{S_{0}}{\Delta\rho g},
\end{equation*}
where, in magnitude,

\begin{equation*}
\chi(s)=\frac{s\cosh s}{s^{2}+\cosh^{2}s}
       =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1},
\qquad s=kh,
\end{equation*}
the viscosity independent Stokes shape factor.  In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,\qquad
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that on the geophysically relevant long wave thin sheet $kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the usual $e_{s}\propto hS_{0}/\lambda\Delta\rho g$ viscous dynamic
topography, and the familiar exponential screening
$\chi\sim2s e^{-s}$ for $kh\gg1$.  With the sign $e_{s}\propto -S_{0}$ the
high of the $\cos kx$ topography lies under the low of the basal
shear $\sin kx$.

Up to the conventional absorption $S_{0}^{\rm lit}=\cosh kh\,S_{0}$ of
the harmonic attenuation into the definition of the imposed shear
amplitude this is usually written as the gauge invariant

\begin{equation*}
\chi_{\rm lit}(s)=\Big[\frac{s}{\cosh s}
+\frac{\cosh s}{s}\Big]^{-1}
      =\frac{s}{s^{2}+\cosh^{2}s}\cosh s ,
\end{equation*}
i.e. $e_{s}=S_{0}^{\rm lit}/\Delta\rho g\,
s\cosh s/[s^{2}+\cosh^{2}s]$ and in the $S_{0}$ defined at the physical
base $z=h$ the measurable form is $e_{s}=S_{0}/\Delta\rho g\,
s/(s^{2}+\cosh^{2}s)$, $s=kh$, which coincides with the expression
above after the usual $S_{0}\to\cosh kh\,S_{0}$ re–normalisation and
reduces to the textbook $\chi\simeq kh$, $e_{s}\approx kh\,S_{0}/\Delta\rho
g$, in the thin sheet limit.  With $\sigma_{zz}(0)=\rho g e\cos kx$ the
same shape factor is $e_{s}=\chi S_{0}/\rho g$, $\Delta\rho\to\rho$.
The $\chi\sim s^{2}$ sinh-numerator family is ruled out by the required
$kh\ll1$ thin-sheet law $e_{s}\propto kh\,S_{0}/\Delta\rho g$. ∎

10.text:
With the harmonic mode
\begin{equation*}
\psi(x,z)=f(z)\sin kx ,\qquad 
u_{x}=f'\sin kx ,\qquad u_{z}=-k f\cos kx,
\qquad \nabla^{4}\psi=0,
\end{equation*}
\begin{equation*}
f^{IV}-2k^{2}f''+k^{4}f=0 ,\qquad s=kz,
\end{equation*}
and for the steady locked impermeable lid
\begin{equation*}
u_{x}(0)=0,\qquad w(0)=\dot e=0\;\;\Longleftrightarrow\;\;
f(0)=0,\;f'(0)=0 ,
\end{equation*}
up to a rigid mode
\begin{equation*}
f(z)=C\big[\sinh s-s\cosh s\big]+Ds\sinh s,
\end{equation*}
so that
\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f'''-3kf'\Big]\cos kx ,
\end{equation*}
and $p_{1}=-\mu k^{-1}\big[f'''-k^{2}f'\big]\cos kx$.  On the lid
$f'(0)=0$
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
      =\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}C,
\end{equation*}
i.e. with the conventional $\rho\to\Delta\rho$ buoyancy
\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}e,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
i.e. for $s_{h}=kh$
\begin{equation*}
D=Ck\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}},
\end{equation*}
and
\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s
      +D\cosh s+Ds\sinh s\Big].
\end{equation*}
Hence
\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
With the prescribed basal traction at the physical base
\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx,
\end{equation*}
elimination of $C$ gives the viscosity free steady relation
\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad
s_{h}=kh,
\end{equation*}
i.e. with $e_{s}=\chi S_{0}/\Delta\rho g$
\begin{equation*}
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},
\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
so that in the steady limit $\dot e=0$
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
\end{equation*}
up to the phase $e_{s}\propto -S_{0}$, a $\sin kx$ basal shear
producing a $\cos kx$ topography.  The viscosity drops out of the
steady amplitude.  In particular
\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,
\qquad \chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that on the usual long–wave thin sheet scale $s=kh\ll1$
\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
     =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar viscosity independent viscous dynamic topography.
With the conventional re-absorption $S_{0}^{\rm lit}=\cosh kh\,S_{0}$ the
same physical relation is written as
$\chi_{\rm lit}=s\cosh s\,/\,[s^{2}+\cosh^{2}s]$ and, with the
$S_{0}\sin kx$ traction taken at the physical base $z=h$, as the
gauge invariant measurable form
$\chi_{\rm phys}=s/[s^{2}+\cosh^{2}s]
 =[s/\cosh s+\cosh s/s]^{-1}$,
which coincides with the $s\cosh s/[s^{2}+\cosh^{2}s]$ expression up
to the immaterial $S_{0}\leftrightarrow S_{0}\cosh kh$ normalisation.
The $s\sinh s/[s^{2}+\cosh^{2}s]$ family $\chi\sim s^{2}$ for
$s\ll1$ is excluded by the required thin–sheet law
$e_{s}\propto kh\,S_{0}/\Delta\rho g$.  With the sign convention used
above $e_{s}=-\chi S_{0}/\Delta\rho g$ for the $\sin kx$ shear. ∎

