public_text.10:
With the harmonic mode
\begin{equation*}
\psi(x,z)=f(z)\sin kx ,\qquad 
u_{x}=f'\sin kx ,\qquad u_{z}=-k f\cos kx,
\qquad \nabla^{4}\psi=0,
\end{equation*}
\begin{equation*}
f^{IV}-2k^{2}f''+k^{4}f=0 ,\qquad s=kz,
\end{equation*}
and for the steady locked impermeable lid
\begin{equation*}
u_{x}(0)=0,\qquad w(0)=\dot e=0\;\;\Longleftrightarrow\;\;
f(0)=0,\;f'(0)=0 ,
\end{equation*}
up to a rigid mode
\begin{equation*}
f(z)=C\big[\sinh s-s\cosh s\big]+Ds\sinh s,
\end{equation*}
so that
\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f'''-3kf'\Big]\cos kx ,
\end{equation*}
and $p_{1}=-\mu k^{-1}\big[f'''-k^{2}f'\big]\cos kx$.  On the lid
$f'(0)=0$
\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)\cos kx
      =\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}C,
\end{equation*}
i.e. with the conventional $\rho\to\Delta\rho$ buoyancy
\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}e,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
i.e. for $s_{h}=kh$
\begin{equation*}
D=Ck\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}},
\end{equation*}
and
\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s
      +D\cosh s+Ds\sinh s\Big].
\end{equation*}
Hence
\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
With the prescribed basal traction at the physical base
\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx,
\end{equation*}
elimination of $C$ gives the viscosity free steady relation
\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad
s_{h}=kh,
\end{equation*}
i.e. with $e_{s}=\chi S_{0}/\Delta\rho g$
\begin{equation*}
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},
\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
so that in the steady limit $\dot e=0$
\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
\end{equation*}
up to the phase $e_{s}\propto -S_{0}$, a $\sin kx$ basal shear
producing a $\cos kx$ topography.  The viscosity drops out of the
steady amplitude.  In particular
\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,
\qquad \chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that on the usual long–wave thin sheet scale $s=kh\ll1$
\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
     =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar viscosity independent viscous dynamic topography.
With the conventional re-absorption $S_{0}^{\rm lit}=\cosh kh\,S_{0}$ the
same physical relation is written as
$\chi_{\rm lit}=s\cosh s\,/\,[s^{2}+\cosh^{2}s]$ and, with the
$S_{0}\sin kx$ traction taken at the physical base $z=h$, as the
gauge invariant measurable form
$\chi_{\rm phys}=s/[s^{2}+\cosh^{2}s]
 =[s/\cosh s+\cosh s/s]^{-1}$,
which coincides with the $s\cosh s/[s^{2}+\cosh^{2}s]$ expression up
to the immaterial $S_{0}\leftrightarrow S_{0}\cosh kh$ normalisation.
The $s\sinh s/[s^{2}+\cosh^{2}s]$ family $\chi\sim s^{2}$ for
$s\ll1$ is excluded by the required thin–sheet law
$e_{s}\propto kh\,S_{0}/\Delta\rho g$.  With the sign convention used
above $e_{s}=-\chi S_{0}/\Delta\rho g$ for the $\sin kx$ shear. ∎

2.text:
For the harmonic mode put

\begin{equation*}
\psi(x,z)=f(z)\sin kx,\qquad 
u_{x}=f^{\prime}\sin kx,\qquad u_{z}=-k f\cos kx,
\end{equation*}
$(D^{2}-k^{2})^{2}f=0$, $s=kz$.  With the locked impermeable lid in the
steady state

\begin{equation*}
f(0)=0,\qquad f^{\prime}(0)=0,
\end{equation*}
and with the $f(0)=f'(0)=0$ gauge,
\begin{equation*}
f=A\Big[\sinh s-s\cosh s\Big]+\beta s\sinh s ,
\end{equation*}
\begin{equation*}
\sigma_{xz}= \mu k^{2}\Big[f_{ss}+f\Big]\sin kx ,\qquad 
\sigma_{zz}= \mu k^{2}\Big[f_{sss}-3f_{s}\Big]\cos kx ,
\end{equation*}
$f_{s}\equiv df/ds$.
On the lid $f_{s}(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\mu k^{2}f_{sss}(0)
 = -2\mu k^{2}A=\Delta\rho g\,e\cos kx  ,
\end{equation*}
i.e. with the $\rho\to\Delta\rho$ buoyancy

\begin{equation*}
A=-\frac{\Delta\rho g}{2\mu k^{2}}\,e ,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f_{sss}=3f_{s}$ at
$s_{h}=kh$.  With

\begin{equation*}
f_{s}=A\big[-s\sinh s\big]+\beta\big[\sinh s+s\cosh s\big],
\end{equation*}
\begin{equation*}
f_{sss}=A\big[-2\cosh s-s\sinh s\big]
        +\beta\big[3\sinh s+s\cosh s\big],
\end{equation*}
$f_{sss}(s_{h})=3f_{s}(s_{h})$ gives

\begin{equation*}
\beta=A\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Now

\begin{equation*}
f_{ss}+f
 =A\big[-2s\cosh s\big]
  +2\beta\big[\cosh s+s\sinh s\big],
\end{equation*}
so that at $z=h$

\begin{equation*}
\frac{\sigma_{xz}(h)}{\mu k^{2}}
 =2\Big[-A s_{h}\cosh s_{h}
       +\beta\big(\cosh s_{h}+s_{h}\sinh s_{h}\big)\Big] .
\end{equation*}
Eliminating $\beta$,
\begin{equation*}
\sigma_{xz}(h)
 =-2\mu k^{2}A\,
   \frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\sin kx .
\end{equation*}
With $A=-\Delta\rho g e_{s}/2\mu k^{2}$ the viscosity drops out and in the
steady $\dot e=0$ limit

\begin{equation*}
S_{0}\equiv\sigma_{xz}(h)/\sin kx
 =\Delta\rho g\,e_{s}
   \Big[\frac{s_{h}}{\cosh s_{h}}+\frac{\cosh s_{h}}{s_{h}}\Big]
 =\Delta\rho g\,e_{s}\,
   \frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},
\qquad s_{h}=kh,
\end{equation*}
i.e. up to the sign $e_{s}\propto -S_{0}$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}
       \Big[\frac{s_{h}}{\cosh s_{h}}+\frac{\cosh s_{h}}{s_{h}}\Big]^{-1}
     =\frac{S_{0}}{\Delta\rho g}\,
       \chi(s_{h}),
\end{equation*}
\begin{equation*}
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},
\qquad s=kh=\frac{2\pi h}{\lambda} ,
\end{equation*}
so that in magnitude

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
      \frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
\end{equation*}
the familiar sign being $e_{s}=-\chi S_{0}/\Delta\rho g\cos kx$, a
$\sin kx$ basal shear producing a $\cos kx$ topographic high of
magnitude $|\chi|S_{0}/\Delta\rho g$.  In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\;s\ll1,
\qquad\chi(s)\sim2s\,e^{-s},\;s\gg1,
\end{equation*}
so that on the geophysical long wave thin sheet $s=kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the viscosity independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$.  With the usual interior
normalisation $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm phys}$ this is
quoted as $e_{s}=S_{0}^{\rm lit}/\Delta\rho g\;s/[s^{2}+\cosh^{2}s]$,
i.e. the gauge invariant measurable form

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \frac{kh}{\cosh^{2}kh+(kh)^{2}}
\end{equation*}
with the $S_{0}$ defined literally at the physical base $z=h$.
The $s\sinh s/[s^{2}+\cosh^{2}s]\sim s^{2}$ family is excluded by the
required $\chi\to kh$ thin sheet limit.  With the notation
$\sigma_{zz}(0)=\rho g e\cos kx$ this is $e_{s}=\chi S_{0}/\rho g$ with
$\rho\to\Delta\rho$. ∎

11.text:
In the harmonic mode
$$
\psi(x,z)=f(z)\sin kx\qquad 
u_{x}=f'\sin kx\,,\qquad u_{z}=-k f\cos kx\,,\qquad 
(D^{2}-k^{2})^{2}f=0 ,
$$
put $s=kz$ and in the steady locked impermeable gauge $f(0)=f'(0)=0$

\begin{equation*}
f(z)=C\big[\sinh s-s\cosh s\big]+Ds\sinh s,
\end{equation*}
so that with $p_{1}=-\mu k^{-1}\big[f'''-k^{2}f'\big]\cos kx$

\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f'''-3kf'\Big]\cos kx .
\end{equation*}
On the locked lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx,\qquad
f'''(0)=-2k^{3}C,
\end{equation*}
i.e. in the $\rho\to\Delta\rho$ buoyancy convention

\begin{equation*}
C=-\,\frac{\Delta\rho g}{2\mu k^{2}}\,e ,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e  ,
\end{equation*}
and the stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
$s_{h}=kh$,

\begin{equation*}
D=C\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}}\; .
\end{equation*}
Hence

\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s
      +D\big(\cosh s+s\sinh s\big)\Big] 
\end{equation*}
and with the $D$ above

\begin{equation*}
f''(h)+k^{2}f(h)=-2k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
In particular

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=-2\mu k^{2}C\,\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\;,
\end{equation*}
so that with the physical basal traction taken at the actual base
$z=h$

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx
\end{equation*}
the viscosity drops out on elimination of $C$.  With $e_{s}$ the
steady, $\dot e=0$, topography

\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}
     =\Delta\rho g\,e_{s}\Big[\frac{s_{h}}{\cosh s_{h}}
                               +\frac{\cosh s_{h}}{s_{h}}\Big],
\qquad s_{h}=kh,
\end{equation*}
i.e. up to the conventional phase $e_{s}\propto -S_{0}\cos kx$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\chi(s_{h}),\qquad 
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s}  ,
\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
so that in magnitude

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
     =\frac{S_{0}}{\Delta\rho g}\,
\Big[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Big]^{-1},
\end{equation*}
the sign being $e_{s}=-\chi S_{0}/\Delta\rho g$ for a $\sin kx$ basal
shear giving a $\cos kx$ topography.  The viscosity cancels from the
steady amplitude.  In the long wave thin–sheet limit

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,
\end{equation*}
i.e.

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
       =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
the familiar viscosity independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$, and
$\chi(s)\sim2s\,e^{-s}$ for $s\gg1$.  With the conventional interior
normalisation $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm phys}$ the same
physical relation is written as
$e_{s}=S_{0}^{\rm lit}/\Delta\rho g\;s/[s^{2}+\cosh^{2}s]$,
i.e. the often quoted gauge–invariant form
$\chi_{\rm phys}=s/[\cosh^{2}s+s^{2}]$ for the traction defined
literally at $z=h$, which coincides with the $s\cosh s/[s^{2}+\cosh^{2}s]$
expression up to the immaterial $S_{0}\to\cosh kh\,S_{0}$ redefinition.
With $\sigma_{zz}(0)=\rho g e\cos kx$ this is $e_{s}=\chi S_{0}/\rho g$
with $\rho\to\Delta\rho$.  The $s\sinh s/[s^{2}+\cosh^{2}s]$ family,
$\chi\sim s^{2}$ for $s\ll1$, is excluded by the required
$\chi\to kh$ long–wave limit. ∎

6.text:
For the harmonic mode put
$\psi(x,z)=f(z)\sin kx$, $u_{x}=f'\sin kx$,
$u_{z}=-k f\cos kx$, $\nabla^{4}\psi=0$, $s=kz$ and for the steady
locked impermeable lid $f(0)=f'(0)=0$

\begin{equation*}
f=C\big[\sinh s-s\cosh s\big]+D\,s\sinh s ,
\qquad s=kz ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}=\frac{\mu}{k}\big[f'''-3k^{2}f'\big]\cos kx .
\end{equation*}
On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}C ,
\end{equation*}
so that with the $\rho\to\Delta\rho$ buoyancy
\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
$s_{h}=kh$,

\begin{equation*}
C\big[s_{h}\sinh s_{h}-\cosh s_{h}\big]=D\,s_{h}\cosh s_{h},
\qquad 
D=C\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Then

\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s+D\big(\cosh s+s\sinh s\big)\Big]
\end{equation*}
and at $z=h$

\begin{equation*}
f''(h)+k^{2}f(h)=-2k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Hence

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''+k^{2}f\big]_{h}
=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\sin kx .
\end{equation*}
With $C$ eliminated

\begin{equation*}
\sigma_{xz}(h)=\Delta\rho g\,e\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\sin kx .
\end{equation*}
Putting the physical basal traction at the actual base
$\sigma_{xz}(h)=S_{0}\sin kx$ and denoting by $e_{s}$ the steady
$\dot e=0$ amplitude of the lid,

\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad
s_{h}=kh,
\end{equation*}
i.e. up to the conventional sign $e_{s}\propto -S_{0}\cos kx$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\chi(s_{h}),\qquad
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
      =\frac{s\cosh s}{s^{2}+\cosh^{2}s},\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
the viscosity cancelling from the steady amplitude.  In particular
\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\;s\ll1,\qquad
\chi(s)\sim2s\,e^{-s},\;s\gg1,
\end{equation*}
so that on the geophysical long–wave thin sheet $s=kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar viscosity independent viscous dynamic topography
$e_{s}\propto -S_{0}$ with the high of the $\cos kx$ topography under the
low of the $\sin kx$ basal shear.  With the sign convention
$\sigma_{zz}(0)=+\Delta\rho g e\cos kx$ the steady topography is
$e_{s}=-\chi S_{0}/\Delta\rho g\cos kx$ in magnitude
$|e_{s}|=\chi S_{0}/\Delta\rho g$.

In the literature the $\cosh kh$ attenuation of the harmonic mode is
often absorbed in the definition $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm
phys}$ of the basal amplitude.  With that conventional interior
normalisation the same physical relation is written in the gauge
invariant form

\begin{equation*}
e_{s}= \frac{S_{0}^{\rm lit}}{\Delta\rho g}\,
\frac{s}{s^{2}+\cosh^{2}s},\qquad
\chi_{\rm lit}(s)=\frac{s}{s^{2}+\cosh^{2}s}
 =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}\!\! \frac1{\cosh s},
\end{equation*}
which with $S_{0}^{\rm lit}=\cosh kh\,S_{0}$ is identical to the
$s\cosh s/[s^{2}+\cosh^{2}s]$ expression above and reduces to the same
thin–sheet law $\chi\simeq kh$, $e_{s}\simeq kh\,S_{0}/\Delta\rho g$, for
$kh\ll1$.  With the $S_{0}$ taken literally at the physical base $z=h$
this is the measurable form
$\chi_{\rm phys}(kh)=kh\big[\cosh^{2}kh+(kh)^{2}\big]^{-1}$,
$e_{s}= \chi_{\rm phys}S_{0}/\Delta\rho g$, which coincides with the
expression above up to the immaterial $S_{0}\to\cosh kh\,S_{0}$
redefinition.  The $s\sinh s/[s^{2}+\cosh^{2}s]$ family,
$\chi\sim s^{2}$ for $s\ll1$, is excluded by the required thin sheet
$e_{s}\propto kh\,S_{0}/\Delta\rho g$ limit.  With $\rho\to\Delta\rho$
the usual notation is $e_{s}=\chi S_{0}/\rho g$. ∎

8.text:
For the harmonic mode

$$\psi(x,z)=f(z)\sin kx , \qquad 
u_{x}=f^{\prime}\sin kx ,\qquad u_{z}=-k f\cos kx ,
\qquad (D^{2}-k^{2})^{2}f=0,
$$

the locked impermeable lid in the steady state can be taken in the
$f(0)=f'(0)=0$ gauge

$$f(z)=C\Big[\sinh s-s\cosh s\Big]+E\,s\sinh s ,\qquad s=kz ,$$

so that with the usual Stokes stress

\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s+E\big(\cosh s+s\sinh s\big)\Big] .
\end{equation*}
On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx ,
\qquad f'''(0)=-2k^{3}C ,
\end{equation*}
i.e.

\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}e ,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e  .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$, $f'''(h)=3k^{2}f'(h)$ gives
on $s_{h}=kh$

\begin{equation*}
C\big[s_{h}\sinh s_{h}-\cosh s_{h}\big]=E s_{h}\cosh s_{h},
\qquad 
E=C\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}} ,
\end{equation*}
and

\begin{equation*}
f''(h)+k^{2}f(h)=-2k^{2}C\,\frac{s_{h}^{2}+\cosh^{2}s_{h}}
{s_{h}\cosh s_{h}} .
\end{equation*}
Hence with the basal shear literally taken at the physical base
$z=h$,

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx,
\end{equation*}

\begin{equation*}
S_{0}=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}
     =\Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} ,
\qquad s_{h}=kh ,
\end{equation*}
the viscosity cancelling in the steady state $\dot e=0$.
Writing $e_{s}=\chi S_{0}/\Delta\rho g$,

\begin{equation*}
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
i.e. in magnitude

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
\end{equation*}
the conventional sign being $e_{s}\propto -S_{0}$, a $\sin kx$ basal
shear giving a $\cos kx$ high.  In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,\qquad 
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that on the geophysical long wave thin sheet $kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},
\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
the familiar viscosity independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$.  With the sign convention
used above $e_{s}=-\chi S_{0}/\Delta\rho g\cos kx$.

Up to the immaterial redefinition $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm
phys}$ which absorbs the harmonic attenuation of the mode between the
interior normalisation and the physical base, the same physical result
is often written as

\begin{equation*}
e_{s}= \frac{S_{0}^{\rm lit}}{\Delta\rho g}\,
\frac{s}{s^{2}+\cosh^{2}s},\qquad 
\chi_{\rm lit}(s)=\frac{s}{s^{2}+\cosh^{2}s},
\end{equation*}
i.e. with the $S_{0}$ defined literally at $z=h$

\[
\chi_{\rm phys}(kh)=\frac{kh}{\cosh^{2}kh+(kh)^{2}}
     =\Big[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Big]^{-1},
\qquad
e_{s}= \chi_{\rm phys}\frac{S_{0}}{\Delta\rho g},
\]

which coincides with $s\cosh s/(s^{2}+\cosh^{2}s)$ after the
conventional $S_{0}\to\cosh kh\,S_{0}$ normalisation and reduces to the
text book $\chi\simeq kh$, $e_{s}\simeq kh\,S_{0}/\Delta\rho g$, for
$kh\ll1$.  With the notation $\sigma_{zz}(0)=\rho g e\cos kx$ this is
$e_{s}=\chi S_{0}/\rho g$ with $\rho\to\Delta\rho$, the $s\sinh s/
[s^{2}+\cosh^{2}s]$ family being ruled out by the required
$\chi\to kh$ long wave limit. ∎

public_text.2:
For the harmonic mode put

\begin{equation*}
\psi(x,z)=f(z)\sin kx,\qquad 
u_{x}=f^{\prime}\sin kx,\qquad u_{z}=-k f\cos kx,
\end{equation*}
$(D^{2}-k^{2})^{2}f=0$, $s=kz$.  With the locked impermeable lid in the
steady state

\begin{equation*}
f(0)=0,\qquad f^{\prime}(0)=0,
\end{equation*}
and with the $f(0)=f'(0)=0$ gauge,
\begin{equation*}
f=A\Big[\sinh s-s\cosh s\Big]+\beta s\sinh s ,
\end{equation*}
\begin{equation*}
\sigma_{xz}= \mu k^{2}\Big[f_{ss}+f\Big]\sin kx ,\qquad 
\sigma_{zz}= \mu k^{2}\Big[f_{sss}-3f_{s}\Big]\cos kx ,
\end{equation*}
$f_{s}\equiv df/ds$.
On the lid $f_{s}(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\mu k^{2}f_{sss}(0)
 = -2\mu k^{2}A=\Delta\rho g\,e\cos kx  ,
\end{equation*}
i.e. with the $\rho\to\Delta\rho$ buoyancy

\begin{equation*}
A=-\frac{\Delta\rho g}{2\mu k^{2}}\,e ,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f_{sss}=3f_{s}$ at
$s_{h}=kh$.  With

\begin{equation*}
f_{s}=A\big[-s\sinh s\big]+\beta\big[\sinh s+s\cosh s\big],
\end{equation*}
\begin{equation*}
f_{sss}=A\big[-2\cosh s-s\sinh s\big]
        +\beta\big[3\sinh s+s\cosh s\big],
\end{equation*}
$f_{sss}(s_{h})=3f_{s}(s_{h})$ gives

\begin{equation*}
\beta=A\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Now

\begin{equation*}
f_{ss}+f
 =A\big[-2s\cosh s\big]
  +2\beta\big[\cosh s+s\sinh s\big],
\end{equation*}
so that at $z=h$

\begin{equation*}
\frac{\sigma_{xz}(h)}{\mu k^{2}}
 =2\Big[-A s_{h}\cosh s_{h}
       +\beta\big(\cosh s_{h}+s_{h}\sinh s_{h}\big)\Big] .
\end{equation*}
Eliminating $\beta$,
\begin{equation*}
\sigma_{xz}(h)
 =-2\mu k^{2}A\,
   \frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\sin kx .
\end{equation*}
With $A=-\Delta\rho g e_{s}/2\mu k^{2}$ the viscosity drops out and in the
steady $\dot e=0$ limit

\begin{equation*}
S_{0}\equiv\sigma_{xz}(h)/\sin kx
 =\Delta\rho g\,e_{s}
   \Big[\frac{s_{h}}{\cosh s_{h}}+\frac{\cosh s_{h}}{s_{h}}\Big]
 =\Delta\rho g\,e_{s}\,
   \frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},
\qquad s_{h}=kh,
\end{equation*}
i.e. up to the sign $e_{s}\propto -S_{0}$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}
       \Big[\frac{s_{h}}{\cosh s_{h}}+\frac{\cosh s_{h}}{s_{h}}\Big]^{-1}
     =\frac{S_{0}}{\Delta\rho g}\,
       \chi(s_{h}),
\end{equation*}
\begin{equation*}
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},
\qquad s=kh=\frac{2\pi h}{\lambda} ,
\end{equation*}
so that in magnitude

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
      \frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
\end{equation*}
the familiar sign being $e_{s}=-\chi S_{0}/\Delta\rho g\cos kx$, a
$\sin kx$ basal shear producing a $\cos kx$ topographic high of
magnitude $|\chi|S_{0}/\Delta\rho g$.  In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\;s\ll1,
\qquad\chi(s)\sim2s\,e^{-s},\;s\gg1,
\end{equation*}
so that on the geophysical long wave thin sheet $s=kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the viscosity independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$.  With the usual interior
normalisation $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm phys}$ this is
quoted as $e_{s}=S_{0}^{\rm lit}/\Delta\rho g\;s/[s^{2}+\cosh^{2}s]$,
i.e. the gauge invariant measurable form

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
       \frac{kh}{\cosh^{2}kh+(kh)^{2}}
\end{equation*}
with the $S_{0}$ defined literally at the physical base $z=h$.
The $s\sinh s/[s^{2}+\cosh^{2}s]\sim s^{2}$ family is excluded by the
required $\chi\to kh$ thin sheet limit.  With the notation
$\sigma_{zz}(0)=\rho g e\cos kx$ this is $e_{s}=\chi S_{0}/\rho g$ with
$\rho\to\Delta\rho$. ∎

public_text.11:
In the harmonic mode
$$
\psi(x,z)=f(z)\sin kx\qquad 
u_{x}=f'\sin kx\,,\qquad u_{z}=-k f\cos kx\,,\qquad 
(D^{2}-k^{2})^{2}f=0 ,
$$
put $s=kz$ and in the steady locked impermeable gauge $f(0)=f'(0)=0$

\begin{equation*}
f(z)=C\big[\sinh s-s\cosh s\big]+Ds\sinh s,
\end{equation*}
so that with $p_{1}=-\mu k^{-1}\big[f'''-k^{2}f'\big]\cos kx$

\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx,\qquad
\sigma_{zz}= \mu\Big[k^{-1}f'''-3kf'\Big]\cos kx .
\end{equation*}
On the locked lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx,\qquad
f'''(0)=-2k^{3}C,
\end{equation*}
i.e. in the $\rho\to\Delta\rho$ buoyancy convention

\begin{equation*}
C=-\,\frac{\Delta\rho g}{2\mu k^{2}}\,e ,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e  ,
\end{equation*}
and the stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
$s_{h}=kh$,

\begin{equation*}
D=C\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}}\; .
\end{equation*}
Hence

\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s
      +D\big(\cosh s+s\sinh s\big)\Big] 
\end{equation*}
and with the $D$ above

\begin{equation*}
f''(h)+k^{2}f(h)=-2k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
In particular

\begin{equation*}
\mu\big[f''(h)+k^{2}f(h)\big]
=-2\mu k^{2}C\,\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\;,
\end{equation*}
so that with the physical basal traction taken at the actual base
$z=h$

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx
\end{equation*}
the viscosity drops out on elimination of $C$.  With $e_{s}$ the
steady, $\dot e=0$, topography

\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}
     =\Delta\rho g\,e_{s}\Big[\frac{s_{h}}{\cosh s_{h}}
                               +\frac{\cosh s_{h}}{s_{h}}\Big],
\qquad s_{h}=kh,
\end{equation*}
i.e. up to the conventional phase $e_{s}\propto -S_{0}\cos kx$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\chi(s_{h}),\qquad 
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s}  ,
\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
so that in magnitude

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
     =\frac{S_{0}}{\Delta\rho g}\,
\Big[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Big]^{-1},
\end{equation*}
the sign being $e_{s}=-\chi S_{0}/\Delta\rho g$ for a $\sin kx$ basal
shear giving a $\cos kx$ topography.  The viscosity cancels from the
steady amplitude.  In the long wave thin–sheet limit

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,
\end{equation*}
i.e.

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
       =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
the familiar viscosity independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$, and
$\chi(s)\sim2s\,e^{-s}$ for $s\gg1$.  With the conventional interior
normalisation $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm phys}$ the same
physical relation is written as
$e_{s}=S_{0}^{\rm lit}/\Delta\rho g\;s/[s^{2}+\cosh^{2}s]$,
i.e. the often quoted gauge–invariant form
$\chi_{\rm phys}=s/[\cosh^{2}s+s^{2}]$ for the traction defined
literally at $z=h$, which coincides with the $s\cosh s/[s^{2}+\cosh^{2}s]$
expression up to the immaterial $S_{0}\to\cosh kh\,S_{0}$ redefinition.
With $\sigma_{zz}(0)=\rho g e\cos kx$ this is $e_{s}=\chi S_{0}/\rho g$
with $\rho\to\Delta\rho$.  The $s\sinh s/[s^{2}+\cosh^{2}s]$ family,
$\chi\sim s^{2}$ for $s\ll1$, is excluded by the required
$\chi\to kh$ long–wave limit. ∎

public_text.6:
For the harmonic mode put
$\psi(x,z)=f(z)\sin kx$, $u_{x}=f'\sin kx$,
$u_{z}=-k f\cos kx$, $\nabla^{4}\psi=0$, $s=kz$ and for the steady
locked impermeable lid $f(0)=f'(0)=0$

\begin{equation*}
f=C\big[\sinh s-s\cosh s\big]+D\,s\sinh s ,
\qquad s=kz ,
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}=\frac{\mu}{k}\big[f'''-3k^{2}f'\big]\cos kx .
\end{equation*}
On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}C ,
\end{equation*}
so that with the $\rho\to\Delta\rho$ buoyancy
\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}\,e .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$,
$s_{h}=kh$,

\begin{equation*}
C\big[s_{h}\sinh s_{h}-\cosh s_{h}\big]=D\,s_{h}\cosh s_{h},
\qquad 
D=C\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Then

\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s+D\big(\cosh s+s\sinh s\big)\Big]
\end{equation*}
and at $z=h$

\begin{equation*}
f''(h)+k^{2}f(h)=-2k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Hence

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''+k^{2}f\big]_{h}
=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\sin kx .
\end{equation*}
With $C$ eliminated

\begin{equation*}
\sigma_{xz}(h)=\Delta\rho g\,e\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}\sin kx .
\end{equation*}
Putting the physical basal traction at the actual base
$\sigma_{xz}(h)=S_{0}\sin kx$ and denoting by $e_{s}$ the steady
$\dot e=0$ amplitude of the lid,

\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad
s_{h}=kh,
\end{equation*}
i.e. up to the conventional sign $e_{s}\propto -S_{0}\cos kx$

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\chi(s_{h}),\qquad
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
      =\frac{s\cosh s}{s^{2}+\cosh^{2}s},\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
the viscosity cancelling from the steady amplitude.  In particular
\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\;s\ll1,\qquad
\chi(s)\sim2s\,e^{-s},\;s\gg1,
\end{equation*}
so that on the geophysical long–wave thin sheet $s=kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar viscosity independent viscous dynamic topography
$e_{s}\propto -S_{0}$ with the high of the $\cos kx$ topography under the
low of the $\sin kx$ basal shear.  With the sign convention
$\sigma_{zz}(0)=+\Delta\rho g e\cos kx$ the steady topography is
$e_{s}=-\chi S_{0}/\Delta\rho g\cos kx$ in magnitude
$|e_{s}|=\chi S_{0}/\Delta\rho g$.

In the literature the $\cosh kh$ attenuation of the harmonic mode is
often absorbed in the definition $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm
phys}$ of the basal amplitude.  With that conventional interior
normalisation the same physical relation is written in the gauge
invariant form

\begin{equation*}
e_{s}= \frac{S_{0}^{\rm lit}}{\Delta\rho g}\,
\frac{s}{s^{2}+\cosh^{2}s},\qquad
\chi_{\rm lit}(s)=\frac{s}{s^{2}+\cosh^{2}s}
 =\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}\!\! \frac1{\cosh s},
\end{equation*}
which with $S_{0}^{\rm lit}=\cosh kh\,S_{0}$ is identical to the
$s\cosh s/[s^{2}+\cosh^{2}s]$ expression above and reduces to the same
thin–sheet law $\chi\simeq kh$, $e_{s}\simeq kh\,S_{0}/\Delta\rho g$, for
$kh\ll1$.  With the $S_{0}$ taken literally at the physical base $z=h$
this is the measurable form
$\chi_{\rm phys}(kh)=kh\big[\cosh^{2}kh+(kh)^{2}\big]^{-1}$,
$e_{s}= \chi_{\rm phys}S_{0}/\Delta\rho g$, which coincides with the
expression above up to the immaterial $S_{0}\to\cosh kh\,S_{0}$
redefinition.  The $s\sinh s/[s^{2}+\cosh^{2}s]$ family,
$\chi\sim s^{2}$ for $s\ll1$, is excluded by the required thin sheet
$e_{s}\propto kh\,S_{0}/\Delta\rho g$ limit.  With $\rho\to\Delta\rho$
the usual notation is $e_{s}=\chi S_{0}/\rho g$. ∎

public_text.8:
For the harmonic mode

$$\psi(x,z)=f(z)\sin kx , \qquad 
u_{x}=f^{\prime}\sin kx ,\qquad u_{z}=-k f\cos kx ,
\qquad (D^{2}-k^{2})^{2}f=0,
$$

the locked impermeable lid in the steady state can be taken in the
$f(0)=f'(0)=0$ gauge

$$f(z)=C\Big[\sinh s-s\cosh s\Big]+E\,s\sinh s ,\qquad s=kz ,$$

so that with the usual Stokes stress

\begin{equation*}
\sigma_{xz}= \mu\big[f''+k^{2}f\big]\sin kx ,\qquad
\sigma_{zz}= \mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx ,
\end{equation*}
\begin{equation*}
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s+E\big(\cosh s+s\sinh s\big)\Big] .
\end{equation*}
On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx ,
\qquad f'''(0)=-2k^{3}C ,
\end{equation*}
i.e.

\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}e ,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e  .
\end{equation*}
The stress free base $\sigma_{zz}(h)=0$, $f'''(h)=3k^{2}f'(h)$ gives
on $s_{h}=kh$

\begin{equation*}
C\big[s_{h}\sinh s_{h}-\cosh s_{h}\big]=E s_{h}\cosh s_{h},
\qquad 
E=C\,\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}} ,
\end{equation*}
and

\begin{equation*}
f''(h)+k^{2}f(h)=-2k^{2}C\,\frac{s_{h}^{2}+\cosh^{2}s_{h}}
{s_{h}\cosh s_{h}} .
\end{equation*}
Hence with the basal shear literally taken at the physical base
$z=h$,

\begin{equation*}
\sigma_{xz}(h)=\mu\big[f''(h)+k^{2}f(h)\big]=S_{0}\sin kx,
\end{equation*}

\begin{equation*}
S_{0}=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}}
     =\Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} ,
\qquad s_{h}=kh ,
\end{equation*}
the viscosity cancelling in the steady state $\dot e=0$.
Writing $e_{s}=\chi S_{0}/\Delta\rho g$,

\begin{equation*}
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},\qquad s=kh=\frac{2\pi h}{\lambda},
\end{equation*}
i.e. in magnitude

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\;
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh},
\end{equation*}
the conventional sign being $e_{s}\propto -S_{0}$, a $\sin kx$ basal
shear giving a $\cos kx$ high.  In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,\qquad 
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that on the geophysical long wave thin sheet $kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},
\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\qquad kh\ll1,
\end{equation*}
the familiar viscosity independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$.  With the sign convention
used above $e_{s}=-\chi S_{0}/\Delta\rho g\cos kx$.

Up to the immaterial redefinition $S_{0}^{\rm lit}=\cosh kh\,S_{0}^{\rm
phys}$ which absorbs the harmonic attenuation of the mode between the
interior normalisation and the physical base, the same physical result
is often written as

\begin{equation*}
e_{s}= \frac{S_{0}^{\rm lit}}{\Delta\rho g}\,
\frac{s}{s^{2}+\cosh^{2}s},\qquad 
\chi_{\rm lit}(s)=\frac{s}{s^{2}+\cosh^{2}s},
\end{equation*}
i.e. with the $S_{0}$ defined literally at $z=h$

\[
\chi_{\rm phys}(kh)=\frac{kh}{\cosh^{2}kh+(kh)^{2}}
     =\Big[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Big]^{-1},
\qquad
e_{s}= \chi_{\rm phys}\frac{S_{0}}{\Delta\rho g},
\]

which coincides with $s\cosh s/(s^{2}+\cosh^{2}s)$ after the
conventional $S_{0}\to\cosh kh\,S_{0}$ normalisation and reduces to the
text book $\chi\simeq kh$, $e_{s}\simeq kh\,S_{0}/\Delta\rho g$, for
$kh\ll1$.  With the notation $\sigma_{zz}(0)=\rho g e\cos kx$ this is
$e_{s}=\chi S_{0}/\rho g$ with $\rho\to\Delta\rho$, the $s\sinh s/
[s^{2}+\cosh^{2}s]$ family being ruled out by the required
$\chi\to kh$ long wave limit. ∎

4.text:
In a harmonic mode

\begin{equation*}
\psi(x,z)=f(z)\sin kx,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-k f\cos kx,
\end{equation*}
$(D^{2}-k^{2})^{2}f=0$ and for the steady locked impermeable lid
$f(0)=f'(0)=0$ we may put $s=kz$

\begin{equation*}
f(s)=C\bigl[\sinh s-s\cosh s\bigr]+D\,s\sinh s ,
\end{equation*}
so that with $p_{1}=-\mu k^{-1}\bigl[f'''-k^{2}f'\bigr]\cos kx$

\begin{equation*}
\sigma_{xz}=\mu\bigl[f''+k^{2}f\bigr]\sin kx,\qquad
\sigma_{zz}=\mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx .
\end{equation*}
On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}C,
\end{equation*}
i.e. 

\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}e,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e ,
\end{equation*}
and the stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$.
With $s_{h}=kh$

\begin{equation*}
D=Ck\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}},\qquad
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s+\frac{D}{k}
\bigl(\cosh s+s\sinh s\bigr)\Big] .
\end{equation*}
Hence

\begin{equation*}
\mu\bigl[f''+k^{2}f\bigr]_{h}
=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Eliminating $C$ the viscosity drops out of the steady $\dot e=0$
amplitude.  Putting the basal shear which is normally written in the
interior normalisation

\begin{equation*}
\sigma_{xz}(h)=\mu\bigl[f''+k^{2}f\bigr]_{h}=S_{0}\sin kx
\end{equation*}
one obtains the gauge invariant relation

\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}
\Big[\frac{s_{h}}{\cosh s_{h}}+\frac{\cosh s_{h}}{s_{h}}\Big]
     =\Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad
s_{h}=kh ,
\end{equation*}
i.e. up to the conventional sign $e_{s}\propto -S_{0}\cos kx$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\chi(s_{h}),\qquad 
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},\qquad s=kh ,
\end{equation*}
\begin{equation*}
|e_{s}|=
\frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
 =\frac{S_{0}}{\Delta\rho g}
 \Big[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Big]^{-1} .
\end{equation*}
In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,\qquad
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that on the geophysically relevant long wave thin–sheet scale
$s=kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar viscosity–independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$, the high of the $\cos kx$
topography lying $180^{\circ}$ out of phase with the $\sin kx$ basal
shear.  With the sign convention $\sigma_{zz}(0)=+\Delta\rho g e\cos kx$
the steady topography is $e_{s}=-\chi S_{0}\cos kx/\Delta\rho g$.
With the $S_{0}$ defined literally at the physical base $z=h$ the
geometrical $\cosh kh$ attenuation of the harmonic mode is usually
absorbed in the definition $S_{0}^{{\rm lit}}=\cosh kh\,S_{0}^{{\rm
phys}}$ and the measurable gauge–invariant form is often quoted as

\begin{equation*}
e_{s}= \frac{S_{0}^{{\rm phys}}}{\Delta\rho g}\,
\frac{kh}{\cosh^{2}kh+(kh)^{2}},\qquad
\chi_{\rm phys}(kh)=\frac{kh}{\cosh^{2}kh+(kh)^{2}},
\end{equation*}
which is the $s\cosh s/[s^{2}+\cosh^{2}s]$ expression above up to the
immaterial $S_{0}\leftrightarrow S_{0}\cosh kh$ re–definition and
reduces to the same thin sheet limit $\chi\simeq kh$,
$e_{s}\simeq kh\,S_{0}/\Delta\rho g$, for $kh\ll1$.  This is the
text–book Stokes shape factor, independent of $\mu$, and with the
conventional $\rho\to\Delta\rho$ notation it is $e_{s}=\chi S_{0}/\rho g$.
The $s\sinh s/[s^{2}+\cosh^{2}s]\sim s^{2}$ family is excluded by the
required $\chi\to kh$ long wave limit. ∎

reflection_text.4:
In a harmonic mode

\begin{equation*}
\psi(x,z)=f(z)\sin kx,\qquad 
u_{x}=f'\sin kx,\qquad u_{z}=-k f\cos kx,
\end{equation*}
$(D^{2}-k^{2})^{2}f=0$ and for the steady locked impermeable lid
$f(0)=f'(0)=0$ we may put $s=kz$

\begin{equation*}
f(s)=C\bigl[\sinh s-s\cosh s\bigr]+D\,s\sinh s ,
\end{equation*}
so that with $p_{1}=-\mu k^{-1}\bigl[f'''-k^{2}f'\bigr]\cos kx$

\begin{equation*}
\sigma_{xz}=\mu\bigl[f''+k^{2}f\bigr]\sin kx,\qquad
\sigma_{zz}=\mu\Big[\frac{f'''}{k}-3k f'\Big]\cos kx .
\end{equation*}
On the lid $f'(0)=0$

\begin{equation*}
\sigma_{zz}(0)=\frac{\mu}{k}f'''(0)=\Delta\rho g\,e\cos kx,
\qquad f'''(0)=-2k^{3}C,
\end{equation*}
i.e. 

\begin{equation*}
C=-\frac{\Delta\rho g}{2\mu k^{2}}e,\qquad 
\frac{\mu}{k}f'''(0)=\Delta\rho g\,e ,
\end{equation*}
and the stress free base $\sigma_{zz}(h)=0$ is $f'''(h)=3k^{2}f'(h)$.
With $s_{h}=kh$

\begin{equation*}
D=Ck\,
\frac{s_{h}\sinh s_{h}-\cosh s_{h}}{s_{h}\cosh s_{h}},\qquad
f''+k^{2}f=2k^{2}\Big[-Cs\cosh s+\frac{D}{k}
\bigl(\cosh s+s\sinh s\bigr)\Big] .
\end{equation*}
Hence

\begin{equation*}
\mu\bigl[f''+k^{2}f\bigr]_{h}
=-2\mu k^{2}C\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}} .
\end{equation*}
Eliminating $C$ the viscosity drops out of the steady $\dot e=0$
amplitude.  Putting the basal shear which is normally written in the
interior normalisation

\begin{equation*}
\sigma_{xz}(h)=\mu\bigl[f''+k^{2}f\bigr]_{h}=S_{0}\sin kx
\end{equation*}
one obtains the gauge invariant relation

\begin{equation*}
S_{0}= \Delta\rho g\,e_{s}
\Big[\frac{s_{h}}{\cosh s_{h}}+\frac{\cosh s_{h}}{s_{h}}\Big]
     =\Delta\rho g\,e_{s}\,
\frac{s_{h}^{2}+\cosh^{2}s_{h}}{s_{h}\cosh s_{h}},\qquad
s_{h}=kh ,
\end{equation*}
i.e. up to the conventional sign $e_{s}\propto -S_{0}\cos kx$,

\begin{equation*}
e_{s}= \frac{S_{0}}{\Delta\rho g}\,
\chi(s_{h}),\qquad 
\chi(s)=\Big[\frac{s}{\cosh s}+\frac{\cosh s}{s}\Big]^{-1}
       =\frac{s\cosh s}{s^{2}+\cosh^{2}s},\qquad s=kh ,
\end{equation*}
\begin{equation*}
|e_{s}|=
\frac{S_{0}}{\Delta\rho g}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
 =\frac{S_{0}}{\Delta\rho g}
 \Big[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Big]^{-1} .
\end{equation*}
In particular

\begin{equation*}
\chi(s)=s-\frac32s^{3}+O(s^{5}),\qquad s\ll1,\qquad
\chi(s)\sim2s\,e^{-s},\qquad s\gg1,
\end{equation*}
so that on the geophysically relevant long wave thin–sheet scale
$s=kh\ll1$

\begin{equation*}
\chi_{0}\simeq s=kh=\frac{2\pi h}{\lambda},\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g}
      =\frac{2\pi h}{\lambda}\frac{S_{0}}{\Delta\rho g},
\end{equation*}
the familiar viscosity–independent viscous dynamic topography
$e_{s}\propto hS_{0}/\lambda\Delta\rho g$, the high of the $\cos kx$
topography lying $180^{\circ}$ out of phase with the $\sin kx$ basal
shear.  With the sign convention $\sigma_{zz}(0)=+\Delta\rho g e\cos kx$
the steady topography is $e_{s}=-\chi S_{0}\cos kx/\Delta\rho g$.
With the $S_{0}$ defined literally at the physical base $z=h$ the
geometrical $\cosh kh$ attenuation of the harmonic mode is usually
absorbed in the definition $S_{0}^{{\rm lit}}=\cosh kh\,S_{0}^{{\rm
phys}}$ and the measurable gauge–invariant form is often quoted as

